/* ================= Extra Reading & Writing practice, set 2 (BrainBurst 1.2) =================
   15 more questions per skill, weighted toward harder ones. The correct answer is written first;
   positions are shuffled when the app loads. Researchers and studies named here are fictional
   unless a fact is common knowledge. */
drillSet('wic', 2, [
  { d: 1, ps: 'The library asked visitors to speak ______ so that others could read without being disturbed.', p: Q_WIC, o: ['quietly', 'loudly', 'rarely', 'angrily'], a: 0, x: 'Not disturbing readers means speaking **quietly**.', w: ['', 'Speaking loudly would disturb readers.', '“Rarely” is about how often, not how loudly, people speak.', 'Speaking angrily doesn’t address disturbing others.'] },
  { d: 1, ps: 'Because the soup was too ______ to eat, Leo waited a few minutes for it to cool.', p: Q_WIC, o: ['hot', 'cold', 'salty', 'small'], a: 0, x: 'Waiting for soup to cool means it was too **hot**.', w: ['', 'Cold soup wouldn’t need to cool down.', 'Waiting for it to cool wouldn’t fix saltiness.', 'Waiting for it to cool wouldn’t change its size.'] },
  { d: 1, ps: 'The mountain path was so ______ that the hikers had to walk in single file.', p: Q_WIC, o: ['narrow', 'wide', 'flat', 'famous'], a: 0, x: 'Walking in single file is necessary on a **narrow** path.', w: ['', 'On a wide path, hikers could walk side by side.', 'A flat path doesn’t force hikers into single file.', 'Being famous doesn’t affect how people walk on it.'] },
  { d: 2, ps: 'The scientist’s talk was highly ______: she explained each idea with everyday examples, and no one in the audience left confused.', p: Q_WIC, o: ['accessible', 'technical', 'controversial', 'repetitive'], a: 0, x: 'Everyday examples that leave no one confused make the talk easy to understand: **accessible**.', w: ['', 'A technical talk would be hard for a general audience to follow.', 'Nothing suggests the talk caused disagreement.', 'Nothing suggests she repeated herself; the clue is how easy it was to follow.'] },
  { d: 2, ps: 'Although the new law was meant to help small farms, its effects were ______: some farms benefited, while others lost money.', p: Q_WIC, o: ['mixed', 'uniform', 'immediate', 'invisible'], a: 0, x: 'Some farms gained and others lost, so the effects were **mixed**.', w: ['', '“Uniform” means the same everywhere, but the effects differed from farm to farm.', 'The text is about how the effects varied, not how quickly they came.', 'Farms clearly gained or lost money, so the effects were visible.'] },
  { d: 2, ps: 'The two reports ______ on most points but disagree about how much the project will cost.', p: Q_WIC, o: ['agree', 'argue', 'depend', 'insist'], a: 0, x: '“But disagree about cost” contrasts with what the reports do on most points: **agree**.', w: ['', '“Argue on most points” doesn’t contrast with disagreeing about cost.', '“Depend on most points” doesn’t make sense here.', '“Insist on most points” doesn’t set up the contrast with disagreeing.'] },
  { d: 2, ps: 'The team’s early success **fueled** hopes that it might win the championship.', p: Q_MEAN('fueled'), o: ['strengthened', 'powered with gasoline', 'burned', 'refilled'], a: 0, x: 'Early wins made hopes grow, so “fueled” means **strengthened**.', w: ['', 'That’s the literal meaning for engines; hopes don’t run on gasoline.', 'Hopes weren’t destroyed; they grew.', '“Refilled” suggests the hopes had run out, which the text doesn’t say.'] },
  { d: 2, ps: 'The museum’s new director has a **clear** vision for the collection: every exhibit should connect art to everyday life.', p: Q_MEAN('clear'), o: ['definite', 'transparent', 'empty', 'cloudless'], a: 0, x: 'Her vision is specific and firmly stated, so “clear” means **definite**.', w: ['', '“Transparent” is the meaning for glass or water, not a vision.', '“Empty” is the meaning in “a clear desk”; her vision has specific content.', '“Cloudless” is the meaning for the sky.'] },
  { d: 3, ps: 'The diplomat’s statement was carefully ______, offering sympathy to both countries without assigning blame to either.', p: Q_WIC, o: ['impartial', 'inflammatory', 'partisan', 'apologetic'], a: 0, x: 'Treating both sides equally and blaming neither is **impartial**.', w: ['', '“Inflammatory” means likely to stir up anger, the opposite of a careful, balanced statement.', '“Partisan” means taking one side, but the statement favored neither country.', 'Nothing suggests the diplomat was apologizing; the point is that no one was blamed.'] },
  { d: 3, ps: 'Early reviews of the novel were ______, but over the following decades, critics came to regard it as a masterpiece.', p: Q_WIC, o: ['dismissive', 'rapturous', 'anonymous', 'prophetic'], a: 0, x: '“But” contrasts early reviews with later praise, so the early reviews were negative: **dismissive**.', w: ['', '“Rapturous” means full of praise, which wouldn’t contrast with calling it a masterpiece later.', 'Whether reviewers were named isn’t the contrast the sentence sets up.', '“Prophetic” would mean the reviews predicted its greatness, which doesn’t contrast with later praise.'] },
  { d: 3, ps: 'The chemist’s method, though ______, produced remarkably pure samples: each step took several days, and the whole process required weeks of careful work.', p: Q_WIC, o: ['laborious', 'effortless', 'careless', 'fleeting'], a: 0, x: 'Weeks of careful, slow work describe a method that is **laborious**.', w: ['', 'Weeks of careful work is the opposite of effortless.', 'The work is described as careful.', '“Fleeting” means brief, but the process took weeks.'] },
  { d: 3, ps: 'Rather than ______ the scandal, the company’s new leaders addressed it openly, publishing a full report on what had gone wrong.', p: Q_WIC, o: ['concealing', 'investigating', 'publicizing', 'acknowledging'], a: 0, x: '“Rather than” sets up the opposite of addressing it openly: **concealing** it.', w: ['', 'Publishing a full report suggests they did investigate, so this doesn’t contrast.', 'Publishing a report is a way of publicizing it, so this doesn’t contrast.', 'Addressing it openly is acknowledging it, so this doesn’t contrast.'] },
  { d: 3, ps: 'The researcher cautioned that the link between the two variables was ______: it appeared in some samples but vanished in others, suggesting that it might be due to chance.', p: Q_WIC, o: ['tenuous', 'robust', 'proportional', 'intentional'], a: 0, x: 'A link that appears only sometimes and might be chance is weak: **tenuous**.', w: ['', '“Robust” means strong and reliable, the opposite of a link that vanishes in some samples.', '“Proportional” describes a type of relationship, not how reliable it is.', 'Variables don’t have intentions; the point is that the link is weak.'] },
  { d: 3, ps: 'Though the senator **entertained** the proposal for several weeks, she ultimately voted against it.', p: Q_MEAN('entertained'), o: ['considered', 'amused', 'hosted', 'performed'], a: 0, x: 'She thought about the proposal before rejecting it, so “entertained” means **considered**.', w: ['', '“Amused” is the meaning for an audience, not a proposal.', '“Hosted” is the meaning for guests.', '“Performed” is the meaning for a show.'] },
  { d: 3, ps: 'The poet’s later work is marked by ______: where her early poems used elaborate imagery, her later ones rely on a few plain words.', p: Q_WIC, o: ['austerity', 'extravagance', 'ambiguity', 'nostalgia'], a: 0, x: 'Moving from elaborate imagery to a few plain words is a move toward severe simplicity: **austerity**.', w: ['', '“Extravagance” describes the elaborate early work, not the plain later work.', 'Plain words don’t suggest unclear meaning; the contrast is about simplicity.', 'Nothing suggests the later poems look back longingly at the past.'] }
]);
drillSet('tsp', 2, [
  { d: 1, ps: 'Sunflowers are not just beautiful; they are also useful. Their seeds are eaten by people and birds, and oil pressed from the seeds is used for cooking.', p: Q_PURP, o: ['To describe some of the ways sunflowers are useful', 'To explain how sunflowers turn toward the sun', 'To argue that birds should not eat sunflower seeds', 'To compare sunflowers with other flowers'], a: 0, x: 'After saying sunflowers are useful, the text lists how: food for people and birds, and cooking oil.', w: ['', 'Turning toward the sun isn’t mentioned.', 'The text mentions birds eating the seeds without objecting.', 'No other flowers are mentioned.'] },
  { d: 1, ps: 'Some people think bats are blind, but that is not true. Most bats can see, and many also use echolocation, making sounds and listening for the echoes to find their way in the dark.', p: Q_STRUCT, o: ['It presents a common belief and then corrects it.', 'It describes a problem and then explains its solution.', 'It compares two different kinds of bats.', 'It tells a story about one particular bat.'], a: 0, x: 'The text states a belief (“bats are blind”) and then shows it is false.', w: ['', 'No problem is solved.', 'The text discusses bats in general, not two kinds.', 'No particular bat is described.'] },
  { d: 1, ps: 'The town’s new bike-share program began in May. Riders can pick up a bike at any of 30 stations and return it to any other station. Since May, riders have taken more than 10,000 trips.', p: Q_PURP, o: ['To describe a new program and how much it has been used', 'To explain how bicycles are built', 'To argue that the town should build more roads', 'To compare bike-share programs in different towns'], a: 0, x: 'The text explains how the program works and reports how many trips riders have taken.', w: ['', 'How bikes are built isn’t discussed.', 'Roads aren’t mentioned.', 'Only one town’s program is described.'] },
  { d: 2, ps: 'The tomato is, botanically, a fruit. ==It develops from the flower of the plant and contains the plant’s seeds.== In the kitchen, however, it is usually treated as a vegetable.', p: Q_FUNC, o: ['It explains why the tomato is classified as a fruit.', 'It explains why cooks treat the tomato as a vegetable.', 'It describes how to grow tomatoes at home.', 'It argues that tomatoes should be eaten raw.'], a: 0, x: 'The underlined sentence gives the botanical reasons behind the claim in the first sentence.', w: ['', 'The kitchen view comes in the next sentence, and no reason is given for it.', 'Growing tomatoes isn’t discussed.', 'The text doesn’t argue how tomatoes should be eaten.'] },
  { d: 2, ps: 'Many cities have begun painting the roofs of buildings white. White roofs reflect more sunlight than dark ones, keeping buildings cooler in summer and reducing the need for air conditioning.', p: Q_PURP, o: ['To explain a benefit of painting roofs white', 'To argue that air conditioning should be banned', 'To describe how roofs are built', 'To compare summer weather in different cities'], a: 0, x: 'The text explains what white roofs do: reflect sunlight, keep buildings cool and reduce air conditioning.', w: ['', 'The text says white roofs reduce the need for air conditioning, not that it should be banned.', 'Roof construction isn’t described.', 'Weather in different cities isn’t compared.'] },
  { d: 2, ps: 'Maria had always been afraid of deep water. For years, she stayed in the shallow end of the pool while her friends swam laps. This summer, she signed up for swimming lessons, and by August she could swim across the lake.', p: Q_STRUCT, o: ['It describes a character’s long-standing fear and then how she overcame it.', 'It compares two kinds of swimming lessons.', 'It explains why Maria’s friends liked to swim laps.', 'It describes a lake and the animals that live there.'], a: 0, x: 'The text moves from Maria’s fear to her lessons and her success.', w: ['', 'Only one set of lessons is mentioned.', 'Her friends are mentioned only in passing.', 'The lake is where she swims; it isn’t described.'] },
  { d: 2, ps: 'Octopuses are known for their intelligence. In laboratory studies, they have opened screw-top jars to reach food inside. ==Some have even escaped from their tanks at night and slipped back in before morning.==', p: Q_FUNC, o: ['It adds a further, more surprising example of the intelligence described in the first sentence.', 'It contradicts the claim that octopuses are intelligent.', 'It explains how laboratory tanks are designed.', 'It introduces a new topic unrelated to intelligence.'], a: 0, x: '“Even” signals a more striking example that builds on the jar-opening example.', w: ['', 'Escaping and returning shows cleverness, which supports the claim.', 'Tank design isn’t explained.', 'The escapes are another sign of intelligence, the same topic.'] },
  { d: 2, ps: 'In the 1800s, many doctors believed that diseases were caused by “bad air” rising from rotting matter. Later in the century, scientists such as Louis Pasteur showed that many diseases are caused by microorganisms, an idea that became known as germ theory.', p: Q_PURP, o: ['To describe how an older explanation of disease was replaced by a new one', 'To argue that doctors in the 1800s were careless', 'To explain how microorganisms reproduce', 'To describe Louis Pasteur’s childhood'], a: 0, x: 'The text moves from the “bad air” idea to germ theory, which replaced it.', w: ['', 'The text doesn’t judge the doctors.', 'Reproduction of microorganisms isn’t explained.', 'Pasteur’s childhood isn’t mentioned.'] },
  { d: 3, ps: 'Some economists argue that a tax on sugary drinks will reduce how much of them people drink. ==Critics counter that people will simply buy the drinks in neighboring towns that have no such tax.== A study of one city, however, found that purchases in nearby towns rose only slightly, far less than purchases fell in the city itself.', p: Q_FUNC, o: ['It presents an objection that the final sentence then offers evidence against.', 'It provides evidence that the tax worked as intended.', 'It states the conclusion the text argues for.', 'It explains how the tax was calculated.'], a: 0, x: 'The critics’ objection (people will shop elsewhere) is answered by the study in the last sentence.', w: ['', 'The sentence gives an objection to the tax, not evidence that it worked.', 'The text ends by weakening this objection, so it isn’t the text’s conclusion.', 'The calculation of the tax isn’t discussed.'] },
  { d: 3, ps: 'The letter arrived on a Tuesday, in her brother’s careful handwriting. Lina read the first line, folded the letter, and put it in her pocket. All day she carried it, unopened again, through meetings and errands. Only that night, alone at the kitchen table, did she read the rest.', p: Q_STRUCT, o: ['It describes a character receiving a letter and then putting off reading most of it until she is alone.', 'It describes a conflict between two siblings and how it is resolved.', 'It contrasts a character’s work life with her home life.', 'It explains why a character’s brother decided to write to her.'], a: 0, x: 'Lina reads one line, carries the letter all day, and finishes it only when she is alone that night.', w: ['', 'No conflict is described or resolved.', 'Work and home are settings for her delay, not things being contrasted.', 'The brother’s reasons for writing are never given.'] },
  { d: 3, ps: 'Astronomers had predicted that the planet orbited its star too closely to hold on to an atmosphere. But observations with a space telescope revealed the chemical signature of water vapor in starlight passing through the planet’s edges. The finding has led researchers to reconsider which planets are able to keep their atmospheres.', p: Q_PURP, o: ['To report a finding that went against a prediction and describe how it has affected researchers’ thinking', 'To explain how space telescopes are built', 'To argue that the planet could support human life', 'To describe the history of a planet’s formation'], a: 0, x: 'Prediction (no atmosphere) → finding (water vapor) → effect (researchers reconsider).', w: ['', 'The telescope is only how the observation was made.', 'The text doesn’t discuss human life.', 'The planet’s formation isn’t described.'] },
  { d: 3, ps: 'The novelist spent ten years writing her first book. ==During that time, she worked as a night nurse, writing in the quiet hours between her rounds.== The hospital, with its long corridors and sleepless patients, became the setting of the novel.', p: Q_FUNC, o: ['It provides background that helps explain where the novel is set.', 'It explains why the novel took ten years to publish.', 'It criticizes the hospital where the novelist worked.', 'It summarizes the plot of the novel.'], a: 0, x: 'Her job at the hospital explains why the hospital became the novel’s setting.', w: ['', 'The text says writing took ten years, but the sentence doesn’t explain why.', 'Nothing in the sentence criticizes the hospital.', 'The plot isn’t described.'] },
  { d: 3, ps: 'Many historians describe the invention of the printing press as a sudden revolution. Yet for decades after printing arrived, handwritten manuscripts remained common, and many readers preferred them. Printing did transform European culture, but it did so gradually, over more than a century.', p: Q_STRUCT, o: ['It presents a common view, offers evidence that complicates it, and then states a more qualified conclusion.', 'It describes a problem and then argues that it was never solved.', 'It compares printing in Europe with printing in Asia.', 'It explains step by step how early printing presses worked.'], a: 0, x: 'Common view (sudden revolution) → complication (manuscripts persisted) → qualified conclusion (gradual change).', w: ['', 'No problem is described; the text refines a historical view.', 'Asia isn’t mentioned.', 'How presses worked isn’t explained.'] },
  { d: 3, ps: 'When the city announced plans to build a highway through the old market district, residents organized meetings, wrote letters to newspapers, and gathered thousands of signatures. After two years of protest, the city moved the highway’s route, and the market still stands today.', p: Q_PURP, o: ['To describe how residents’ efforts led a city to change its plans', 'To argue that cities should never build highways', 'To explain how highways are designed', 'To describe the goods sold at the market'], a: 0, x: 'The text describes the residents’ campaign and its result: the highway was moved.', w: ['', 'The text describes one case; it doesn’t argue against all highways.', 'Highway design isn’t explained.', 'The market’s goods aren’t described.'] },
  { d: 3, ps: 'The old clock in the hall had stopped years ago, its hands fixed at ten past four. ==No one in the family had ever tried to repair it.== Grandmother said that ten past four was the hour her husband had left for the war, and that the clock could start again when he came home.', p: Q_FUNC, o: ['It points out a puzzling fact that the next sentence explains.', 'It shows that the family did not care about the clock.', 'It describes the clock’s appearance in detail.', 'It explains why the clock stopped working.'], a: 0, x: 'Leaving a broken clock unrepaired is odd; Grandmother’s explanation in the next sentence accounts for it.', w: ['', 'The next sentence shows the clock matters deeply to the family.', 'The clock’s appearance is described in the first sentence, not this one.', 'The sentence is about not repairing it; why it stopped is never explained.'] }
]);
const Q_CTC_R = who => `Based on the texts, how would ${who} most likely respond to the claim in Text 1?`;
drillSet('ctc', 2, [
  { d: 1, ps: '**Text 1**\nMany people think that cats don’t really care about their owners.\n\n**Text 2**\nIn a study, most pet cats showed signs of stress when their owners left the room and calmed down when the owners returned, much as dogs and young children do.', p: Q_CTC_R('the author of Text 2'), o: ['By suggesting that many cats are attached to their owners', 'By agreeing that cats don’t care about their owners', 'By arguing that dogs are better pets than cats', 'By claiming that cats are never stressed'], a: 0, x: 'Cats getting stressed when owners leave and calming when they return shows attachment, which goes against Text 1.', w: ['', 'The study’s results point the other way.', 'Text 2 compares cats to dogs’ behavior; it doesn’t rank them as pets.', 'The cats showed stress when their owners left.'] },
  { d: 1, ps: '**Text 1**\nSome people say homework should be banned because it takes time away from family and play.\n\n**Text 2**\nStudies suggest that small amounts of homework can help older students remember what they learned in class, though large amounts offer little extra benefit.', p: Q_CTC_R('the author of Text 2'), o: ['By suggesting that some homework may be useful, especially in small amounts', 'By agreeing that all homework should be banned', 'By arguing that students should get as much homework as possible', 'By claiming that homework helps young children most'], a: 0, x: 'Text 2 finds a benefit from small amounts, so it wouldn’t support a complete ban.', w: ['', 'Text 2 finds some benefit, so it wouldn’t support banning all homework.', 'Text 2 says large amounts offer little extra benefit.', 'Text 2 mentions older students, not young children.'] },
  { d: 1, ps: '**Text 1**\nSome people believe that eating lots of carrots gives you excellent night vision.\n\n**Text 2**\nCarrots contain vitamin A, which the eyes need to see in dim light. But for people who already get enough vitamin A, eating extra carrots won’t make night vision any better than normal.', p: Q_CTC_R('the author of Text 2'), o: ['By explaining that carrots support normal night vision but won’t make it better than normal for most people', 'By agreeing that eating extra carrots gives people excellent night vision', 'By claiming that carrots contain no vitamin A', 'By arguing that night vision doesn’t depend on diet at all'], a: 0, x: 'Text 2 agrees that vitamin A matters but says extra carrots don’t improve vision beyond normal.', w: ['', 'Text 2 says extra carrots won’t make night vision better than normal.', 'Text 2 says carrots do contain vitamin A.', 'Text 2 says the eyes need vitamin A, so diet matters.'] },
  { d: 2, ps: '**Text 1**\nElectric scooters are a clean way to travel short distances in cities, since they produce no exhaust.\n\n**Text 2**\nElectric scooters produce no exhaust while being ridden, but making their batteries and frames creates pollution, and many shared scooters last less than a year before they must be replaced.', p: Q_CTC_R('the author of Text 2'), o: ['By pointing out that scooters’ environmental costs come mainly from making and replacing them rather than from riding them', 'By agreeing that scooters have no environmental costs at all', 'By arguing that scooters produce a great deal of exhaust', 'By claiming that most shared scooters last for many years'], a: 0, x: 'Text 2 accepts that riding is clean but adds the pollution from manufacturing and frequent replacement.', w: ['', 'Text 2 describes pollution from making the scooters.', 'Text 2 agrees they produce no exhaust while being ridden.', 'Text 2 says many last less than a year.'] },
  { d: 2, ps: '**Text 1**\nSome researchers argue that dogs understand human words in much the same way people do.\n\n**Text 2**\nIn experiments, dogs responded correctly to familiar commands spoken in a normal tone. But when the same words were spoken in an unusual tone, many dogs failed to respond. Tone, not just the words themselves, appears to guide their responses.', p: Q_CTC_R('the author of Text 2'), o: ['By suggesting that dogs may depend heavily on tone rather than understanding words the way people do', 'By agreeing that dogs understand words exactly as people do', 'By arguing that dogs cannot respond to any commands', 'By claiming that tone has no effect on how dogs respond'], a: 0, x: 'Dogs failed when only the tone changed, so tone matters a lot, unlike word understanding in people.', w: ['', 'The tone results suggest dogs don’t process words the way people do.', 'The dogs responded correctly to familiar commands in a normal tone.', 'Text 2 found tone strongly affected responses.'] },
  { d: 2, ps: '**Text 1**\nHistorians have long assumed that ancient Roman roads were built mainly to move armies.\n\n**Text 2**\nRecords show that Roman roads were used heavily by merchants, travelers and government messengers, and many were built in peaceful regions far from any frontier.', p: Q_CTC_R('the author of Text 2'), o: ['By arguing that the roads served many purposes besides moving armies', 'By agreeing that armies were the only users of the roads', 'By claiming that the Romans built no roads near frontiers', 'By suggesting that merchants rarely used the roads'], a: 0, x: 'Text 2’s records show many non-military users and roads in peaceful areas, which challenges the military-only view.', w: ['', 'Text 2 lists merchants, travelers and messengers as heavy users.', 'Text 2 says many roads were far from frontiers, not that none were near them.', 'Text 2 says merchants used the roads heavily.'] },
  { d: 2, ps: '**Text 1**\nBees play a vital role in pollinating crops such as apples and almonds.\n\n**Text 2**\nMany birds and bats also pollinate plants. In some tropical regions, bats are the main pollinators of trees such as the durian.', p: 'Based on the texts, both authors would most likely agree with which statement?', o: ['Animals can play an important role in pollinating plants.', 'Bees are the only animals that pollinate plants.', 'Bats pollinate apples and almonds.', 'Tropical trees do not need pollinators.'], a: 0, x: 'Text 1 credits bees and Text 2 credits birds and bats, so both see animals as important pollinators.', w: ['', 'Text 2 names birds and bats as pollinators too.', 'Neither text says bats pollinate apples or almonds.', 'Text 2 says bats pollinate tropical trees such as the durian.'] },
  { d: 2, ps: '**Text 1**\nA study found that people who drink coffee live longer than people who don’t, so the researchers recommend coffee for better health.\n\n**Text 2**\nThe coffee drinkers in that study also tended to smoke less and exercise more. Because the study did not account for these differences, it cannot show that coffee itself helps people live longer.', p: Q_CTC_R('the author of Text 2'), o: ['By arguing that other differences between the groups might explain the result', 'By agreeing that everyone should drink coffee', 'By claiming that coffee shortens people’s lives', 'By arguing that smoking has no effect on health'], a: 0, x: 'Text 2 points out that smoking and exercise also differed, so the study can’t credit coffee.', w: ['', 'Text 2 questions the recommendation.', 'Text 2 doesn’t say coffee is harmful; it says the study can’t show a benefit.', 'Text 2 treats smoking as a factor that matters.'] },
  { d: 3, ps: '**Text 1**\nSome linguists argue that young children learn grammar mainly by imitating the sentences they hear.\n\n**Text 2**\nYoung children often produce forms they have never heard adults use, such as “goed” or “mouses.” They apply regular patterns where adults use exceptions. These errors suggest that children are working out rules rather than simply copying.', p: Q_CTC_R('the author of Text 2'), o: ['By pointing to children’s errors as evidence that they apply rules rather than only imitating', 'By agreeing that children learn grammar only by copying adults', 'By arguing that children never make grammatical errors', 'By claiming that adults also say “goed” and “mouses”'], a: 0, x: 'Forms like “goed” can’t be copied from adults, so they show children applying rules.', w: ['', 'Text 2 argues that children do more than copy.', 'Text 2’s whole point rests on children’s errors.', 'Text 2 says children produce these forms without hearing adults use them.'] },
  { d: 3, ps: '**Text 1**\nCity planner Ines Moreau argues that building more housing near city centers will lower rents across the city.\n\n**Text 2**\nEconomist Jalen Brooks agrees that new housing tends to lower rents across a city overall. He notes, however, that on the specific blocks where new luxury buildings go up, rents for nearby older apartments sometimes rise as the neighborhood becomes more desirable.', p: 'Based on the texts, how would Brooks most likely respond to Moreau’s argument?', o: ['By agreeing with her overall prediction while noting that some nearby areas may see rents rise', 'By rejecting the idea that new housing affects rents at all', 'By arguing that new housing raises rents everywhere in a city', 'By claiming that luxury buildings should not be built near city centers'], a: 0, x: 'Brooks accepts the citywide effect but adds a local exception.', w: ['', 'Brooks says new housing tends to lower rents overall.', 'Brooks says rents rise only on some specific blocks.', 'Brooks describes an effect; he doesn’t argue against building.'] },
  { d: 3, ps: '**Text 1**\nThe idea that listening to classical music makes people smarter became popular after a 1993 study found that students scored higher on a spatial reasoning task after listening to Mozart.\n\n**Text 2**\nLater studies found that the improvement was small, lasted only about fifteen minutes, and appeared after listening to almost any music that participants enjoyed, not just Mozart. Researchers suggest that the brief boost reflects improved mood and alertness.', p: 'Based on the texts, how would the researchers in Text 2 most likely respond to the idea described in Text 1?', o: ['By arguing that the effect is brief and probably caused by mood and alertness rather than by classical music in particular', 'By agreeing that Mozart’s music permanently increases intelligence', 'By claiming that listening to music lowers spatial reasoning', 'By arguing that the 1993 study never took place'], a: 0, x: 'Text 2 finds the boost short-lived and tied to enjoyment of any music, explained by mood and alertness.', w: ['', 'Text 2 says the effect lasted only about fifteen minutes.', 'Text 2 found a small improvement, not a decline.', 'Text 2 doesn’t question that the study happened.'] },
  { d: 3, ps: '**Text 1**\nSome biologists argue that the bright colors of many male birds evolved because females prefer brightly colored mates.\n\n**Text 2**\nOthers point out that in some species, bright colors also warn rivals away: males with brighter colors win more contests over territory. In these species, color may serve more than one purpose.', p: Q_CTC_R('the biologists in Text 2'), o: ['By suggesting that female preference may be only one of the reasons bright colors evolved', 'By arguing that females have no preference about color', 'By claiming that brightly colored males lose most contests over territory', 'By agreeing that female preference is the only reason for bright colors'], a: 0, x: 'Text 2 adds rivalry between males as another possible reason, without denying female preference.', w: ['', 'Text 2 doesn’t deny female preference; it adds another purpose.', 'Text 2 says brighter males win more contests.', 'Text 2 says color may serve more than one purpose.'] },
  { d: 3, ps: '**Text 1**\nAuthor Ana Ruiz argues that social media has made people lonelier by replacing face-to-face friendships.\n\n**Text 2**\nA large survey found that people who used social media mainly to message friends they also saw in person reported less loneliness, while those who mostly scrolled through strangers’ posts reported more. How people use social media, the researchers concluded, matters more than how much they use it.', p: 'Based on the texts, how would the researchers in Text 2 most likely respond to Ruiz’s argument?', o: ['By suggesting that social media’s effect on loneliness depends on how people use it', 'By agreeing that all social media use increases loneliness', 'By arguing that social media has no effect on loneliness', 'By claiming that people should stop seeing friends in person'], a: 0, x: 'The survey found different effects for different kinds of use, so a single verdict like Ruiz’s is too simple.', w: ['', 'People who messaged friends they also saw reported less loneliness.', 'The survey found effects in both directions, depending on use.', 'Nothing in Text 2 suggests that.'] },
  { d: 3, ps: '**Text 1**\nArchaeologist Paul Wren claims that the large stone circles in the region were built as calendars, since some of their stones line up with the sunrise on the longest day of the year.\n\n**Text 2**\nArchaeologist Sara Lind notes that with dozens of stones in each circle, some are likely to line up with the sunrise by chance. She also points out that the circles contain burial sites, suggesting that they served as places of ceremony.', p: 'Based on the texts, how would Lind most likely respond to Wren’s claim?', o: ['By questioning whether the alignments are meaningful and proposing a different purpose for the circles', 'By agreeing that the circles were built mainly as calendars', 'By arguing that none of the stones line up with the sunrise', 'By claiming that the circles were built after the burial sites were abandoned'], a: 0, x: 'Lind suggests the alignments could be chance and points to burials as a sign of ceremonial use.', w: ['', 'Lind doubts the calendar evidence and proposes a ceremonial purpose.', 'Lind says some stones are likely to line up by chance, not that none do.', 'Lind doesn’t discuss the order in which the circles and burials came.'] },
  { d: 3, ps: '**Text 1**\nSome educators argue that students learn best when lessons are matched to their preferred learning style, such as visual or auditory.\n\n**Text 2**\nIn controlled studies, students taught in their preferred style did not learn more than students taught in another style. The best method depended on the material instead: maps, for example, are best learned visually, whatever a student’s stated preference.', p: Q_CTC_R('the author of Text 2'), o: ['By arguing that matching lessons to preferred styles doesn’t improve learning and that the material should guide the method', 'By agreeing that every lesson should match each student’s preferred style', 'By claiming that students should never be taught visually', 'By arguing that students learn nothing from maps'], a: 0, x: 'Text 2 found no benefit from matching styles and says the material should decide the method.', w: ['', 'Text 2 found no benefit from matching lessons to preferences.', 'Text 2 says maps are best learned visually.', 'Text 2 uses maps as something students learn well visually.'] }
]);
drillSet('cid', 2, [
  { d: 1, ps: 'Giraffes have very long necks, but they have the same number of neck bones as humans: seven. Each of a giraffe’s neck bones, however, can be more than 25 centimeters long.', p: 'According to the text, how do giraffe necks compare with human necks?', o: ['They have the same number of bones, but each bone is much longer.', 'They have many more bones than human necks do.', 'They have fewer bones than human necks do.', 'They have bones of the same length as human neck bones.'], a: 0, x: 'The text says both have seven neck bones, but a giraffe’s can be more than 25 centimeters long.', w: ['', 'The text says both have seven.', 'The text says both have seven.', 'The text says a giraffe’s neck bones can be more than 25 centimeters long.'] },
  { d: 1, ps: 'The Great Barrier Reef, off the northeast coast of Australia, is the largest coral reef system in the world. It stretches for more than 2,000 kilometers and is home to thousands of species of fish, coral and other sea life.', p: 'According to the text, what is true about the Great Barrier Reef?', o: ['It is the largest coral reef system in the world.', 'It is located off the west coast of Australia.', 'It is home to only a few kinds of fish.', 'It is shorter than 2,000 kilometers.'], a: 0, x: 'The text calls it “the largest coral reef system in the world.”', w: ['', 'The text says it is off the northeast coast.', 'The text says it is home to thousands of species.', 'The text says it stretches for more than 2,000 kilometers.'] },
  { d: 1, ps: 'Tom had never cooked a whole meal by himself. On his mother’s birthday, he followed a recipe step by step, and though the kitchen was a mess afterward, the pasta tasted wonderful.', p: Q_MAIN, o: ['Tom successfully cooks a meal on his own for the first time, for his mother’s birthday.', 'Tom dislikes cooking and avoids it.', 'Tom’s mother teaches him how to make pasta.', 'Tom ruins dinner on his mother’s birthday.'], a: 0, x: 'It’s his first meal on his own, made for his mother’s birthday, and it turns out well.', w: ['', 'Nothing suggests he dislikes cooking.', 'He follows a recipe by himself.', 'The kitchen was messy, but the pasta tasted wonderful.'] },
  { d: 2, ps: 'The Roman city of Pompeii was buried under volcanic ash when Mount Vesuvius erupted in 79 CE. Because the ash preserved buildings, wall paintings and even loaves of bread, the city offers historians an unusually detailed picture of daily life in the Roman Empire.', p: Q_MAIN, o: ['Pompeii’s burial preserved the city in a way that helps historians understand Roman daily life.', 'Mount Vesuvius erupts every few years.', 'Most Roman cities were destroyed by volcanoes.', 'Historians know very little about daily life in Pompeii.'], a: 0, x: 'The text explains how the ash preserved the city and why that matters to historians.', w: ['', 'Only one eruption is mentioned.', 'Only Pompeii is discussed.', 'The text says the city gives an unusually detailed picture.'] },
  { d: 2, ps: 'Many trees in a forest are connected underground by networks of fungi that grow among their roots. Through these networks, older trees can pass water and nutrients to younger trees growing in the shade, helping them survive until they are tall enough to reach the sunlight.', p: 'According to the text, how can older trees help younger ones?', o: ['By passing water and nutrients to them through networks of fungi', 'By dropping leaves that shade them from the sun', 'By growing more slowly to leave room for them', 'By producing seeds that grow into new fungi'], a: 0, x: 'The text says older trees can pass water and nutrients through fungal networks.', w: ['', 'The younger trees are already in shade; the text doesn’t mention leaves helping them.', 'The text doesn’t mention older trees changing their growth.', 'The text doesn’t say trees produce fungi.'] },
  { d: 2, ps: 'The applause had ended, and the theater was nearly empty. Still, Nadia stood on the stage a moment longer, looking out at the rows of seats as if trying to memorize them.', p: 'Based on the text, what can most reasonably be inferred about Nadia?', o: ['She wants to remember this moment.', 'She has forgotten her lines.', 'She is waiting for the audience to return.', 'She is unhappy with her performance.'], a: 0, x: 'Staying on stage and looking “as if trying to memorize” the seats shows she wants to hold on to the moment.', w: ['', 'The performance is over, so her lines don’t matter now.', 'Nothing suggests she expects the audience back.', 'Nothing suggests disappointment; she lingers fondly.'] },
  { d: 2, ps: 'Some fish can change color in seconds. The Nassau grouper, a large reef fish, can shift from a pattern of dark stripes to a nearly solid pale color, possibly to blend in with its surroundings or to signal to other fish.', p: Q_MAIN, o: ['Some fish, such as the Nassau grouper, can change color quickly, possibly for camouflage or communication.', 'The Nassau grouper is the largest fish on coral reefs.', 'All reef fish are striped.', 'Fish change color only when they are sick.'], a: 0, x: 'The text introduces quick color change and gives the grouper as an example, with two possible reasons.', w: ['', 'The text calls it large but doesn’t say it’s the largest.', 'Only the grouper’s stripes are mentioned.', 'The text suggests camouflage or signaling, not sickness.'] },
  { d: 2, ps: 'In the 1920s and 1930s, farmers on the Great Plains of the United States plowed up millions of acres of native grassland to plant wheat. When a severe drought struck in the 1930s, the bare soil dried out, and strong winds carried it away in enormous dust storms. The period became known as the Dust Bowl.', p: Q_MAIN, o: ['Farming practices combined with a severe drought led to the dust storms of the Dust Bowl.', 'Wheat grows best in dry, windy places.', 'The Dust Bowl was caused by a single storm.', 'Farmers planted grass to stop the dust storms.'], a: 0, x: 'The text links the plowed-up grassland and the drought to the dust storms.', w: ['', 'The text doesn’t say wheat grows best in drought.', 'The text describes many dust storms over a period of years.', 'Farmers plowed up grass; they didn’t plant it.'] },
  { d: 3, ps: 'Grandpa’s workshop smelled of sawdust and machine oil, and every tool hung on its own nail, outlined in black paint. After he moved into the care home, my mother kept the workshop exactly as he had left it. Sometimes I found her there in the evenings, not working on anything, just sitting on his stool.', p: 'Based on the text, what can most reasonably be inferred about the narrator’s mother?', o: ['She finds comfort in being in her father’s workshop.', 'She plans to take up woodworking.', 'She wants to sell her father’s tools.', 'She is searching the workshop for a missing tool.'], a: 0, x: 'She keeps the workshop unchanged and sits there without working, which suggests it comforts her and keeps her close to her father.', w: ['', 'She sits there “not working on anything.”', 'She keeps everything exactly as it was.', 'She sits quietly; nothing suggests she’s looking for anything.'] },
  { d: 3, ps: 'Economists once assumed that people make financial decisions by carefully weighing costs and benefits. But experiments show that choices often depend on how options are described. For example, a medical treatment described as having a “90 percent survival rate” is chosen far more often than one described as having a “10 percent death rate,” though the two descriptions mean the same thing.', p: Q_MAIN, o: ['The way options are described can change people’s decisions, which challenges the idea that people always weigh costs and benefits carefully.', 'Most people prefer medical treatments with high death rates.', 'Economists have always known that wording affects decisions.', 'People make better medical decisions than financial ones.'], a: 0, x: 'The example shows identical options chosen differently because of wording, undercutting the older assumption.', w: ['', 'People chose the treatment described by its survival rate more often.', 'The text says economists once assumed careful weighing.', 'The text doesn’t compare medical and financial decisions.'] },
  { d: 3, ps: 'The painter Agnes Martin covered large square canvases with faint pencil lines and pale bands of color. Some viewers dismissed the works as empty. Martin, however, described them as attempts to express feelings such as innocence and joy, and many viewers report a sense of calm when they look at the paintings for a long time.', p: Q_MAIN, o: ['Martin’s seemingly simple paintings were meant to express emotions and can affect viewers who look closely.', 'Martin’s paintings were rejected by every viewer who saw them.', 'Martin painted only with pencil.', 'Martin regretted making such plain paintings.'], a: 0, x: 'The text contrasts the “empty” criticism with Martin’s aims and viewers’ calm responses.', w: ['', 'Many viewers report feeling calm, so not every viewer rejected them.', 'She also used pale bands of color.', 'Nothing suggests regret; she explained what she meant to express.'] },
  { d: 3, ps: 'Mrs. Tan always insisted that she didn’t care for birthday fuss. Yet when her grandchildren arrived with a cake, she disappeared into the bedroom and came back wearing the pearl earrings she saved for special occasions.', p: 'Based on the text, what can most reasonably be inferred about Mrs. Tan?', o: ['She is more pleased by the celebration than she admits.', 'She is annoyed that her grandchildren ignored her wishes.', 'She wants to leave before the cake is served.', 'She has forgotten that it is her birthday.'], a: 0, x: 'Putting on her special-occasion earrings shows she treats the visit as special, despite what she says.', w: ['', 'Dressing up for the occasion suggests pleasure, not annoyance.', 'She dresses up and returns, so she isn’t trying to leave.', 'She responds to the birthday cake, so she knows what it’s for.'] },
  { d: 3, ps: 'Glass looks solid, but its atoms are arranged randomly, like those of a liquid, rather than in the orderly pattern of a crystal. This is why scientists call glass an “amorphous solid.” Contrary to a popular myth, however, old windows are not thicker at the bottom because glass slowly flows over time; they were simply made unevenly.', p: Q_MAIN, o: ['Glass has an unusual atomic structure, but it does not flow over time as a popular myth claims.', 'Glass is a liquid that flows slowly over centuries.', 'Old windows were made with great precision.', 'Glass atoms are arranged in an orderly crystal pattern.'], a: 0, x: 'The text explains glass’s liquid-like structure and then corrects the myth about flowing windows.', w: ['', 'The text calls glass a solid and rejects the flowing myth.', 'The text says old windows were made unevenly.', 'The text says glass atoms are arranged randomly.'] },
  { d: 3, ps: 'Researchers tracking humpback whales in the South Pacific noticed that the whales’ songs changed every few years. A new song would appear in one population and then spread from group to group across the ocean, until nearly all the males were singing the new version.', p: 'Based on the text, what is most strongly suggested?', o: ['Humpback whales can learn new songs from whales in other groups.', 'Humpback whales sing the same song throughout their lives.', 'Only female humpback whales sing.', 'Each group of humpback whales sings a song no other group knows.'], a: 0, x: 'A song spreading from group to group means whales pick it up from other groups.', w: ['', 'The text says songs change every few years.', 'The text says the males sing the new version.', 'The new songs spread until nearly all males sang them.'] },
  { d: 3, ps: 'On some summer days, visitors to the Austrian village of Hallstatt outnumber its residents by more than ten to one. Local officials have limited the number of tour buses allowed each day and asked visitors to respect residents’ privacy, hoping to keep the village livable while still welcoming guests.', p: Q_MAIN, o: ['Hallstatt is trying to balance tourism with the needs of its residents.', 'Hallstatt has banned all tourists.', 'Most of Hallstatt’s residents work as tour guides.', 'Hallstatt receives very few visitors.'], a: 0, x: 'The village limits buses and asks for respect while “still welcoming guests”: a balance.', w: ['', 'It limits tour buses but still welcomes guests.', 'Residents’ jobs aren’t mentioned.', 'Visitors can outnumber residents ten to one.'] }
]);
const Q_ILL = 'Which quotation most effectively illustrates the claim?';
const Q_SUP = who => `Which finding, if true, would most directly support ${who}?`;
const Q_WKN = who => `Which finding, if true, would most directly weaken ${who}?`;
drillSet('coet', 2, [
  { d: 1, ps: 'In a short story, the narrator describes her dog, Biscuit, as loyal.', p: Q_ILL, o: ['“Every afternoon, Biscuit waited by the gate until I came home from school, no matter the weather.”', '“Biscuit had brown fur and floppy ears.”', '“Biscuit loved to chase squirrels in the park.”', '“We adopted Biscuit from a shelter when he was two.”'], a: 0, x: 'Waiting every day in any weather shows loyalty.', w: ['', 'His looks don’t show loyalty.', 'Chasing squirrels doesn’t show loyalty.', 'Where he came from doesn’t show loyalty.'] },
  { d: 1, ps: 'A student claims that the school garden produced more vegetables this year than last year.', p: Q_SUP('the student’s claim'), o: ['The garden produced 120 kilograms of vegetables this year, compared with 85 kilograms last year.', 'More students volunteered in the garden this year.', 'The garden grew tomatoes and beans in both years.', 'The garden produced about the same amount of vegetables in both years.'], a: 0, x: 'Only one finding compares the amounts produced, and it shows an increase.', w: ['', 'More volunteers doesn’t show more vegetables.', 'Growing the same crops says nothing about the amount.', 'The same amount would weaken the claim, not support it.'] },
  { d: 1, ps: 'In a poem, the speaker expresses happiness at the arrival of spring.', p: Q_ILL, o: ['“At last the frost is gone, and every branch / bursts into blossom, and my heart with it.”', '“The days grow longer in the month of March.”', '“The winter was long and cold this year.”', '“The birds return each year to the same old trees.”'], a: 0, x: 'A heart “bursting into blossom” with the branches shows joy at spring’s arrival.', w: ['', 'This states a fact about March without any feeling.', 'This is about winter, not happiness at spring.', 'This describes birds returning without expressing happiness.'] },
  { d: 2, ps: 'A researcher claims that a new fertilizer increases the size of tomatoes.', p: Q_SUP('the researcher’s claim'), o: ['Tomatoes from plants given the fertilizer were, on average, 20 percent heavier than tomatoes from otherwise identical plants that were not.', 'The fertilizer is made from recycled plant material.', 'Farmers who tried the fertilizer said it was easy to use.', 'Tomatoes grown with and without the fertilizer were about the same size.'], a: 0, x: 'Heavier tomatoes compared with identical untreated plants directly support the claim.', w: ['', 'What the fertilizer is made of doesn’t show its effect.', 'Ease of use doesn’t show its effect on size.', 'No difference in size would weaken the claim.'] },
  { d: 2, ps: 'A historian claims that home refrigerators changed how American families shopped for food.', p: Q_SUP('the historian’s claim'), o: ['After home refrigerators became common, many families switched from shopping almost every day to shopping once or twice a week.', 'Early refrigerators were expensive.', 'Some families kept ice boxes before refrigerators were invented.', 'Refrigerators come in many sizes today.'], a: 0, x: 'A shift in shopping habits after refrigerators spread directly supports the claim.', w: ['', 'Price doesn’t show a change in shopping.', 'Ice boxes are background; they don’t show a change caused by refrigerators.', 'Today’s sizes say nothing about how shopping changed.'] },
  { d: 2, ps: 'In a novel, the narrator describes her sister Mara as both brave and careless.', p: Q_ILL, o: ['“Mara would leap from the highest rock into the river without a second thought, and she never once checked how deep the water was.”', '“Mara was afraid of the dark until she was twelve.”', '“Mara always checked the depth of the water before she swam.”', '“Mara loved the river more than anyone in our family.”'], a: 0, x: 'Leaping from the highest rock shows bravery; never checking the depth shows carelessness.', w: ['', 'This shows fear, not bravery or carelessness.', 'This shows caution, the opposite of carelessness.', 'Loving the river shows neither bravery nor carelessness.'] },
  { d: 2, ps: 'City officials claim that new recycling bins caused the increase in recycling in their city.', p: Q_WKN('the officials’ claim'), o: ['Recycling increased by the same amount in a nearby city that did not get new bins.', 'Residents said they liked the design of the new bins.', 'The new bins are larger than the old ones.', 'Recycling in the city rose the month after the new bins arrived.'], a: 0, x: 'If recycling rose just as much without new bins, something else probably caused the increase.', w: ['', 'Liking the bins doesn’t test whether they caused the increase.', 'Larger bins fit the claim; they don’t weaken it.', 'A rise right after the bins arrived supports the claim.'] },
  { d: 2, ps: 'A psychologist claims that people are more likely to help a stranger when they are in a good mood.', p: Q_SUP('the psychologist’s claim'), o: ['People who had just found a coin in a phone booth were more likely to help a stranger pick up dropped papers than people who hadn’t found a coin.', 'Most people say they enjoy helping others.', 'Strangers are more likely to ask for help on busy streets.', 'People in good moods and bad moods helped strangers equally often.'], a: 0, x: 'Finding a coin lifts mood, and those people helped more: a direct test of the claim.', w: ['', 'What people say they enjoy doesn’t link mood to helping.', 'Where strangers ask for help says nothing about mood.', 'Equal helping would weaken the claim.'] },
  { d: 3, ps: 'A biologist hypothesizes that a species of desert beetle collects drinking water from morning fog by tilting its body so that droplets roll down its back to its mouth.', p: Q_SUP('the biologist’s hypothesis'), o: ['Beetles placed in a chamber with fog tilted their bodies and gained water weight, while beetles in a chamber without fog did not tilt.', 'The beetles live in one of the driest deserts on Earth.', 'The beetles’ backs are covered in small bumps.', 'Other desert insects get water from the plants they eat.'], a: 0, x: 'Tilting only in fog, and gaining water when they did, directly supports the proposed behavior.', w: ['', 'A dry habitat explains why water matters but doesn’t show how they collect it.', 'Bumps might matter, but this doesn’t show the tilting behavior.', 'Other insects’ methods don’t test this beetle’s behavior.'] },
  { d: 3, ps: 'An economist claims that a city’s new minimum wage caused restaurants to employ fewer workers.', p: Q_WKN('the economist’s claim'), o: ['Restaurant employment in the city rose after the minimum wage took effect, at about the same rate as in nearby cities without the change.', 'Some restaurant owners said they were worried about the new minimum wage.', 'The new minimum wage was higher than the old one.', 'Restaurant employment in the city fell after the new minimum wage, while it rose in nearby cities.'], a: 0, x: 'If employment rose just as it did elsewhere, the wage didn’t cause a drop.', w: ['', 'Worries don’t show what actually happened to jobs.', 'This is true by definition and doesn’t test the claim.', 'This would support the claim, not weaken it.'] },
  { d: 3, ps: 'In a short story, the narrator suggests that her father’s strictness came from his own difficult childhood.', p: Q_ILL, o: ['“He set rules for everything, and only years later did I learn that he had spent his own childhood fending for himself, with no one to set any rules at all.”', '“My father was strict about bedtimes and homework.”', '“My father grew up on a farm outside the city.”', '“He told funny stories about his childhood that made us laugh.”'], a: 0, x: 'The claim links his strictness to his childhood. Only this quotation shows both and connects them.', w: ['', 'This shows strictness but not its connection to his childhood.', 'This mentions his childhood but not his strictness or any hardship.', 'Funny stories don’t suggest a difficult childhood.'] },
  { d: 3, ps: 'Researchers hypothesize that a certain plant releases a chemical from its roots that slows the growth of nearby plants of other species.', p: Q_SUP('the researchers’ hypothesis'), o: ['Seedlings of other species grew more slowly in soil that had held the plant’s roots than in identical soil that had not, even after the plant itself was removed.', 'The plant grows well in many types of soil.', 'Other plants near the plant receive less sunlight because of its large leaves.', 'Seedlings grew at the same rate in soil that had and had not held the plant’s roots.'], a: 0, x: 'Slower growth in the soil alone, with the plant gone, points to something the roots left behind.', w: ['', 'Growing well doesn’t show it releases anything.', 'Shade is a different explanation, which wouldn’t support the chemical hypothesis.', 'Equal growth would weaken the hypothesis.'] },
  { d: 3, ps: 'A literary scholar argues that a novel published anonymously in 1850 was written by the poet Eliza Hart, pointing to similarities between the novel’s language and Hart’s poems.', p: Q_WKN('the scholar’s argument'), o: ['The publisher’s records show that payment for the novel was sent to a different writer, who described working on it in his diary.', 'Hart wrote several poems about the sea, a setting that also appears in the novel.', 'The novel sold more copies than any of Hart’s books of poetry.', 'Hart once said that she admired novelists.'], a: 0, x: 'Payment records and a diary pointing to another writer strongly suggest someone else wrote it.', w: ['', 'A shared setting fits the scholar’s argument.', 'Sales figures don’t say who wrote the novel.', 'Admiring novelists doesn’t show she did or didn’t write this one.'] },
  { d: 3, ps: 'A sociologist claims that residents of the town of Millford trust local news sources more than national ones.', p: Q_SUP('the sociologist’s claim'), o: ['In a survey of 1,000 Millford residents, 72 percent said they trusted local newspapers “a great deal,” compared with 38 percent who said the same of national newspapers.', 'Millford has two local newspapers.', 'Many Millford residents read national news online.', 'National newspapers cover more stories than local ones.'], a: 0, x: 'The survey directly compares trust in local and national sources.', w: ['', 'The number of papers doesn’t show how much they’re trusted.', 'Reading national news doesn’t show how much residents trust it.', 'Coverage doesn’t show trust.'] },
  { d: 3, ps: 'In a poem, the speaker suggests that a painful memory has become less sharp over time.', p: Q_ILL, o: ['“The wound that once could stop my breath / is now a scar I trace without a flinch.”', '“I still remember every word you said.”', '“That winter was the hardest of my life.”', '“Time moves slowly in a quiet house.”'], a: 0, x: 'A wound that has become a scar the speaker can touch calmly shows the pain fading.', w: ['', 'This shows the memory is still sharp.', 'This shows the pain but not that it has faded.', 'This is about time passing slowly, not a memory fading.'] }
]);
drillSet('coeq', 2, [
  { d: 1, ps: 'A teacher asked 100 students to name their favorite fruit. Apples were the most popular choice: ______', ch: { t: 'bar', title: 'Favorite fruit (100 students)', x: ['Apple', 'Banana', 'Orange', 'Grape'], s: [{ n: 'Students', v: [34, 22, 18, 26] }] }, p: Q_GRAPH, o: ['34 students chose apples, more than chose any other fruit.', '22 students chose bananas.', 'more students chose grapes than chose oranges.', '18 students chose oranges.'], a: 0, x: 'Only one choice shows apples were chosen most often.', w: ['', 'This is about bananas.', 'This compares grapes and oranges, not apples.', 'This is about oranges.'] },
  { d: 1, ps: 'A town recorded its rainfall for four months. April was the wettest of these months: ______', ch: { t: 'table', title: 'Monthly rainfall', head: ['Month', 'Rainfall (cm)'], rows: [['January', '8'], ['February', '6'], ['March', '9'], ['April', '12']] }, p: Q_DATA, o: ['April had 12 centimeters of rain, more than any other month shown.', 'February had 6 centimeters of rain.', 'March had more rain than January.', 'January had 8 centimeters of rain.'], a: 0, x: 'Only one choice compares April with the other months.', w: ['', 'This is about February.', 'This compares March and January.', 'This is about January.'] },
  { d: 1, ps: 'A student measured a bean plant every week for five weeks. The plant grew taller every week: ______', ch: { t: 'line', title: 'Height of bean plant (cm)', x: ['Week 1', 'Week 2', 'Week 3', 'Week 4', 'Week 5'], s: [{ n: 'Height', v: [2, 4, 7, 11, 16] }] }, p: Q_GRAPH, o: ['its height rose from 2 centimeters in week 1 to 16 centimeters in week 5, increasing each week.', 'it was 7 centimeters tall in week 3.', 'it grew 5 centimeters between weeks 4 and 5.', 'it was 2 centimeters tall in week 1.'], a: 0, x: 'Only one choice describes growth across all the weeks.', w: ['', 'One week’s height doesn’t show it grew every week.', 'One week’s growth doesn’t show it grew every week.', 'One week’s height doesn’t show it grew every week.'] },
  { d: 2, ps: 'Two groups of students took the same test before and after a month of study. One group practiced with sample questions; the other did not. The student concluded that the practice group improved more: ______', ch: { t: 'table', title: 'Average test scores', head: ['Group', 'Before', 'After'], rows: [['Practice', '70', '82'], ['No practice', '71', '74']] }, p: Q_DATA, o: ['the practice group’s average rose by 12 points, while the other group’s rose by only 3.', 'the practice group averaged 82 after the month.', 'the no-practice group averaged 71 before the month.', 'both groups’ averages rose.'], a: 0, x: '“Improved more” compares the gains, so both gains are needed.', w: ['', 'One final score doesn’t show which group improved more.', 'One starting score doesn’t show improvement.', 'Both rising doesn’t show which rose more.'] },
  { d: 2, ps: 'A city tracked visitors to its three museums. Of the three, only the Science Museum had fewer visitors in 2023 than in 2022: ______', ch: { t: 'table', title: 'Museum visitors (thousands)', head: ['Museum', '2022', '2023'], rows: [['Art', '120', '150'], ['Science', '200', '190'], ['History', '90', '110']] }, p: Q_DATA, o: ['visitors to the Science Museum fell from 200,000 to 190,000, while the other two museums gained visitors.', 'the Science Museum had 200,000 visitors in 2022.', 'the Art Museum gained 30,000 visitors.', 'the History Museum had the fewest visitors in both years.'], a: 0, x: 'The statement needs the Science Museum’s drop and the other museums’ gains.', w: ['', 'This gives one year only, so no drop is shown.', 'This is about the Art Museum only.', 'This is about the History Museum and doesn’t mention the Science Museum’s drop.'] },
  { d: 2, ps: 'A student compared average monthly temperatures in two cities. City A was colder than City B in every month shown, but the gap between them narrowed: ______', ch: { t: 'line', title: 'Average temperature (°C)', x: ['Jan', 'Feb', 'Mar', 'Apr'], s: [{ n: 'City A', v: [2, 4, 9, 14] }, { n: 'City B', v: [10, 11, 13, 16] }] }, p: Q_GRAPH, o: ['City A was 8 degrees colder than City B in January but only 2 degrees colder in April.', 'City B averaged 16°C in April.', 'City A warmed from 2°C in January to 14°C in April.', 'Both cities were warmer in April than in January.'], a: 0, x: 'A narrowing gap needs the difference at two times: 8 degrees, then 2 degrees.', w: ['', 'One city in one month doesn’t show the gap.', 'This shows City A warming but not the gap with City B.', 'Both warming doesn’t show the gap narrowing.'] },
  { d: 2, ps: 'In a study, adults slept for different amounts of time and then took a reaction-time test. The researcher noted that more sleep was associated with faster reactions: ______', ch: { t: 'table', title: 'Average reaction time', head: ['Hours of sleep', 'Reaction time (milliseconds)'], rows: [['5', '410'], ['6', '370'], ['7', '330'], ['8', '300']] }, p: Q_DATA, o: ['reaction times fell steadily from 410 milliseconds after 5 hours of sleep to 300 milliseconds after 8 hours.', 'reaction time after 6 hours of sleep was 370 milliseconds.', 'adults who slept 8 hours had a reaction time of 300 milliseconds.', 'the slowest reaction time was 410 milliseconds.'], a: 0, x: 'An association needs the whole pattern: more sleep, lower (faster) times.', w: ['', 'One value doesn’t show a pattern.', 'One value doesn’t show a pattern.', 'One value doesn’t show a pattern.'] },
  { d: 2, ps: 'A library counted books checked out by genre in one month. Fantasy was the most borrowed genre, with mystery second: ______', ch: { t: 'bar', title: 'Books checked out', x: ['Mystery', 'Fantasy', 'History', 'Science'], s: [{ n: 'Books', v: [340, 410, 150, 180] }] }, p: Q_GRAPH, o: ['410 fantasy books and 340 mystery books were checked out, more than any other genre.', '150 history books were checked out.', 'more science books than history books were checked out.', '340 mystery books were checked out.'], a: 0, x: 'The statement ranks fantasy first and mystery second, so it needs both numbers compared with the rest.', w: ['', 'This is about history only.', 'This compares science and history.', 'This gives mystery only, not fantasy.'] },
  { d: 3, ps: 'A health department surveyed adults about exercise in 2015 and 2023. An official claims that the increase in regular exercise was largest among people 55 and older.', ch: { t: 'table', title: 'Adults exercising at least three times a week', head: ['Age group', '2015', '2023'], rows: [['18–34', '52%', '61%'], ['35–54', '44%', '48%'], ['55 and older', '30%', '41%']] }, p: 'Which choice best describes data from the table that support the official’s claim?', o: ['The share among people 55 and older rose by 11 percentage points, more than in either younger group (9 and 4 points).', 'In 2023, 61% of people aged 18–34 exercised regularly, the highest of any group.', 'The share among people 55 and older was the lowest of the three groups in both years.', 'The share among people aged 35–54 rose from 44% to 48%.'], a: 0, x: 'The claim is about the size of the increase, so the answer must compare increases across groups.', w: ['', 'This is about the level in one year, not the increase.', 'Being lowest doesn’t show the largest increase.', 'This gives one other group’s increase without comparing.'] },
  { d: 3, ps: 'A student claims that in each of the three cities in the table, more commuters take the bus than the train.', ch: { t: 'table', title: 'Share of commuters', head: ['City', 'Bus', 'Train'], rows: [['A', '34%', '21%'], ['B', '18%', '29%'], ['C', '27%', '12%']] }, p: 'Which choice best describes data from the table that weaken the student’s claim?', o: ['In City B, 29% of commuters take the train, compared with 18% who take the bus.', 'In City A, 34% of commuters take the bus, compared with 21% who take the train.', 'In City C, more than twice as many commuters take the bus as take the train.', 'City A has the highest share of bus commuters.'], a: 0, x: 'City B is the exception: more commuters take the train than the bus.', w: ['', 'This supports the claim.', 'This supports the claim.', 'This doesn’t compare bus and train in a way that weakens the claim.'] },
  { d: 3, ps: 'A publisher tracked sales of printed books and e-books from 2018 to 2022. E-book sales first exceeded printed book sales in ______', ch: { t: 'line', title: 'Sales (millions)', x: ['2018', '2019', '2020', '2021', '2022'], s: [{ n: 'Printed', v: [50, 48, 45, 43, 40] }, { n: 'E-books', v: [20, 28, 37, 44, 47] }] }, p: Q_GRAPH, o: ['2021.', '2019.', '2020.', '2022.'], a: 0, x: 'In 2021, e-books (44) passed printed books (43) for the first time.', w: ['', 'In 2019, e-books (28) were far below printed books (48).', 'In 2020, e-books (37) were still below printed books (45).', 'E-books were ahead in 2022, but they first passed printed books in 2021.'] },
  { d: 3, ps: 'Volunteers planted trees at two sites. A researcher claims that at both sites, a higher share of trees survived when they were watered weekly than when they were watered monthly.', ch: { t: 'table', title: 'Trees surviving after one year', head: ['Site', 'Watered weekly', 'Watered monthly'], rows: [['Site 1', '45 of 50', '38 of 50'], ['Site 2', '27 of 30', '24 of 30']] }, p: 'Which choice best describes data from the table that support the researcher’s claim?', o: ['At Site 1, 90% of trees watered weekly survived, versus 76% watered monthly; at Site 2, the figures were 90% and 80%.', 'More trees were planted at Site 1 than at Site 2.', 'At Site 2, 24 trees watered monthly survived.', 'At Site 1, 45 trees watered weekly survived.'], a: 0, x: 'The claim compares survival rates at both sites, so the answer must give both comparisons.', w: ['', 'The number planted doesn’t compare watering schedules.', 'One count at one site doesn’t make a comparison.', 'One count at one site doesn’t make a comparison.'] },
  { d: 3, ps: 'An entomologist hypothesizes that a species of leaf beetle prefers warmer leaves. She recorded where beetles were found on leaves of different temperatures.', ch: { t: 'table', title: 'Where beetles were found', head: ['Leaf temperature', 'Share of beetles'], rows: [['15°C', '8%'], ['20°C', '17%'], ['25°C', '31%'], ['30°C', '44%']] }, p: 'Which choice best describes data from the table that support the hypothesis?', o: ['The share of beetles rose steadily as leaf temperature increased, from 8% at 15°C to 44% at 30°C.', '17% of beetles were found on leaves at 20°C.', 'Fewer than half of the beetles were found on the warmest leaves.', 'The coolest leaves had the fewest beetles.'], a: 0, x: 'A preference for warmth shows up as more beetles on warmer leaves across the whole range.', w: ['', 'One value doesn’t show a preference.', 'This seems to point the other way and ignores the trend.', 'This shows only one end of the pattern.'] },
  { d: 3, ps: 'A reviewer claims that although Phone X had the longest battery life of the three phones tested, it was not the heaviest.', ch: { t: 'table', title: 'Phone test results', head: ['Phone', 'Battery life (hours)', 'Weight (grams)'], rows: [['X', '31', '190'], ['Y', '26', '210'], ['Z', '22', '175']] }, p: 'Which choice best describes data from the table that support the reviewer’s claim?', o: ['Phone X lasted the longest (31 hours), but Phone Y was heavier (210 grams compared with 190).', 'Phone Z was the lightest phone, at 175 grams.', 'Phone Y’s battery lasted 26 hours.', 'Phone X weighed 190 grams.'], a: 0, x: 'The claim has two parts: X lasts longest, and another phone is heavier. Only one choice shows both.', w: ['', 'This doesn’t mention battery life or show X isn’t heaviest.', 'This is about Phone Y’s battery only.', 'X’s weight alone doesn’t show another phone is heavier.'] },
  { d: 3, ps: 'A researcher claims that students who slept at least 8 hours scored higher on average than students who slept less, on both the math test and the reading test.', ch: { t: 'table', title: 'Average test scores', head: ['Sleep', 'Math', 'Reading'], rows: [['Less than 8 hours', '72', '78'], ['8 hours or more', '80', '79']] }, p: 'Which choice best describes data from the table that support the researcher’s claim?', o: ['Students who slept at least 8 hours averaged 80 in math and 79 in reading, compared with 72 and 78 for students who slept less.', 'Students who slept less than 8 hours averaged 78 in reading.', 'Students who slept at least 8 hours scored higher in math than in reading.', 'The difference in math scores between the groups was 8 points.'], a: 0, x: 'The claim covers both tests, so the answer must compare both groups on math and reading.', w: ['', 'One group on one test doesn’t make a comparison.', 'This compares two tests for one group, not the two groups.', 'This covers math only, not reading.'] }
]);
drillSet('inf', 2, [
  { d: 1, ps: 'Penguins live almost entirely in the Southern Hemisphere, while polar bears live in the Arctic, in the far north. Therefore, polar bears and penguins ______', p: Q_INF, o: ['rarely, if ever, meet in the wild.', 'often hunt together.', 'eat the same foods.', 'live on the same ice sheets.'], a: 0, x: 'They live at opposite ends of the planet, so they don’t meet in the wild.', w: ['', 'They live at opposite ends of the planet.', 'Diet isn’t discussed.', 'Penguins live in the south and polar bears in the north.'] },
  { d: 1, ps: 'Maya’s houseplant was wilting, and its soil was completely dry. She watered it, and by evening its leaves were standing up again. This suggests that the plant had been wilting because ______', p: Q_INF, o: ['it needed water.', 'it had too much sunlight.', 'it was too old to grow.', 'its pot was too large.'], a: 0, x: 'The plant recovered right after watering, so lack of water caused the wilting.', w: ['', 'Sunlight didn’t change; water did.', 'It recovered, so it wasn’t too old to grow.', 'The pot didn’t change; water did.'] },
  { d: 1, ps: 'Some animals hibernate during winter, when food is scarce. While they hibernate, their body temperature drops and their heartbeat slows, so they use very little energy. This allows them to ______', p: Q_INF, o: ['survive the winter without eating much.', 'grow larger during the winter.', 'hunt more during the winter.', 'stay warmer than in summer.'], a: 0, x: 'Using very little energy lets them get through a time of scarce food.', w: ['', 'Using little energy doesn’t lead to growth.', 'They are hibernating, not hunting.', 'Their body temperature drops.'] },
  { d: 2, ps: 'In a study, people serving themselves from a buffet were given either a small plate or a large one. Everyone could take as much food as they wanted, yet people with small plates served themselves less and ate less. This suggests that ______', p: Q_INF, o: ['the size of a plate can influence how much people eat.', 'people with large plates were hungrier.', 'small plates make food taste better.', 'everyone eats the same amount regardless of plate size.'], a: 0, x: 'The only difference was plate size, and it changed how much people ate.', w: ['', 'Plates were assigned, so hunger wasn’t the difference.', 'Taste wasn’t measured.', 'People with small plates ate less.'] },
  { d: 2, ps: 'A bookstore noticed that books displayed on a table near the front door sold more copies than the same books shelved at the back of the store. To sell more of a particular book, the store’s manager should probably ______', p: Q_INF, o: ['display it on the table near the front door.', 'move it to the back of the store.', 'raise its price.', 'stop ordering it.'], a: 0, x: 'Books near the door sold more, so that’s where to put a book you want to sell.', w: ['', 'Books at the back sold fewer copies.', 'Price wasn’t part of the observation.', 'Stopping orders wouldn’t sell more copies.'] },
  { d: 2, ps: 'In a study, one group of children was praised for being smart after solving puzzles, and another group was praised for working hard. When offered a choice of new puzzles, children praised for effort more often chose harder ones. This suggests that ______', p: Q_INF, o: ['praising effort may encourage children to take on challenges.', 'children praised for being smart are better at puzzles.', 'all children prefer easy puzzles.', 'praise has no effect on children’s choices.'], a: 0, x: 'The kind of praise was the only difference, and effort praise led to choosing harder puzzles.', w: ['', 'The study measured which puzzles children chose, not their skill.', 'Children praised for effort often chose harder puzzles.', 'The two kinds of praise led to different choices.'] },
  { d: 2, ps: 'Mountain climbers often feel short of breath at high altitudes, even when they are resting. At high altitudes, each breath of air contains less oxygen. Climbers’ shortness of breath is therefore most likely caused by ______', p: Q_INF, o: ['getting less oxygen with each breath.', 'climbing too quickly.', 'the cold temperatures.', 'carrying heavy packs.'], a: 0, x: 'They’re short of breath even at rest, and the text says each breath has less oxygen.', w: ['', 'They’re short of breath even while resting.', 'Cold isn’t mentioned.', 'They feel it even at rest, without climbing.'] },
  { d: 2, ps: 'An umbrella shop found that its sales were highest in the rainiest months and lowest in the driest months. Based on this pattern, the shop can expect to ______', p: Q_INF, o: ['sell more umbrellas during a rainy month than during a dry one.', 'sell the same number of umbrellas every month.', 'sell more umbrellas in dry months.', 'stop selling umbrellas when it rains.'], a: 0, x: 'Sales follow the rain, so rainy months should bring more sales.', w: ['', 'Sales change with the weather.', 'Dry months had the lowest sales.', 'Rainy months had the highest sales.'] },
  { d: 3, ps: 'A city installed brighter streetlights on half of its streets. Over the following year, reported crimes fell on the newly lit streets. They also fell by a similar amount on the streets that kept the old lights. This suggests that ______', p: Q_INF, o: ['the brighter lights may not have been the main reason for the drop in crime.', 'brighter lights cause crime to fall.', 'the old lights caused crime to rise.', 'crime rose across the city that year.'], a: 0, x: 'Crime fell just as much without new lights, so something else likely explains the drop.', w: ['', 'The equal drop on unchanged streets undercuts this.', 'Crime fell on the old-light streets too.', 'Crime fell on both kinds of streets.'] },
  { d: 3, ps: 'Researchers found that in one forest, the trees with the most fungus on their roots grew the fastest. But when researchers added the fungus to the roots of slow-growing trees, those trees’ growth did not change. These results suggest that ______', p: Q_INF, o: ['the fungus may not be what makes the fast-growing trees grow quickly.', 'the fungus slows tree growth.', 'slow-growing trees cannot be studied.', 'all trees in the forest grow at the same rate.'], a: 0, x: 'Adding fungus didn’t speed growth, so the link between fungus and fast growth may not be cause and effect.', w: ['', 'Growth didn’t change, so the fungus didn’t slow it either.', 'The researchers did study slow-growing trees.', 'Some trees grew faster than others.'] },
  { d: 3, ps: 'Historians studying a medieval town found that its population records show a sharp drop in 1349. Records from many other towns in the region show a similar drop in the same year, and a plague is known to have spread through the region in 1348 and 1349. Together, these findings suggest that the town’s population ______', p: Q_INF, o: ['probably fell because of the plague.', 'fell because people moved to other towns in the region.', 'was not affected by events in the region.', 'grew rapidly after 1349.'], a: 0, x: 'A region-wide drop at the time of a known plague points to the plague.', w: ['', 'Other towns also lost people, so they weren’t gaining the town’s residents.', 'Its drop matched the region’s.', 'The records describe a drop; nothing is said about growth afterward.'] },
  { d: 3, ps: 'Most songbirds learn their songs by listening to adult birds of their species. In one experiment, young birds raised without hearing any adult songs produced simple, unusual songs as adults, while young birds that heard recordings of adult songs sang normal songs. This suggests that ______', p: Q_INF, o: ['hearing adult songs is important for young songbirds to develop normal songs.', 'songbirds are born knowing their species’ songs.', 'recordings make birds sing unusual songs.', 'young songbirds cannot sing at all.'], a: 0, x: 'Only birds that heard adult songs developed normal ones, so hearing them matters.', w: ['', 'Birds raised without hearing adults sang unusual songs, so the song isn’t fully inborn.', 'Birds that heard recordings sang normal songs.', 'Both groups sang; one group’s songs were unusual.'] },
  { d: 3, ps: 'A company let employees choose to work from home two days a week. Those who chose to do so reported higher job satisfaction than those who did not. However, the employees who chose to work from home had also, on average, worked at the company longer and held more senior positions. It is therefore possible that ______', p: Q_INF, o: ['the higher satisfaction is due partly to differences in experience and position, not only to working from home.', 'working from home lowers job satisfaction.', 'senior employees are not allowed to work from home.', 'all employees chose to work from home.'], a: 0, x: '“However” introduces other differences between the groups that could explain the satisfaction gap.', w: ['', 'Those working from home reported higher satisfaction.', 'Senior employees were among those who chose to work from home.', 'Some employees did not choose to work from home.'] },
  { d: 3, ps: 'Astronomers noticed that a star appears to wobble slightly back and forth every 4 days. A large planet orbiting a star pulls on it, making the star wobble with the same period as the planet’s orbit. The astronomers concluded that the star probably ______', p: Q_INF, o: ['has a large planet that orbits it about every 4 days.', 'has no planets.', 'is about to explode.', 'orbits another star every 4 years.'], a: 0, x: 'The wobble’s period matches the planet’s orbit, so a planet circles the star about every 4 days.', w: ['', 'The wobble suggests a planet is pulling on it.', 'Nothing in the text suggests an explosion.', 'The wobble repeats every 4 days, not 4 years.'] },
  { d: 3, ps: 'In the 1990s, a lake’s water became much clearer. During the same years, zebra mussels, small shellfish that filter tiny particles out of the water, spread through the lake in huge numbers. Earlier efforts to reduce pollution had not noticeably changed the water’s clarity. These facts suggest that ______', p: Q_INF, o: ['the zebra mussels may have been largely responsible for the clearer water.', 'pollution in the lake increased in the 1990s.', 'zebra mussels make water cloudier.', 'the earlier pollution efforts caused the water to clear.'], a: 0, x: 'The clearing came with the mussels, which filter particles, not with the earlier efforts.', w: ['', 'The text doesn’t say pollution increased.', 'They filter particles out, which clears water.', 'The earlier efforts had not noticeably changed clarity.'] }
]);
drillSet('bnd', 2, [
  { d: 1, ps: 'The concert starts at ______ please arrive early to find a seat.', p: Q_SEC, o: ['eight;', 'eight,', 'eight', 'eight, and,'], a: 0, x: 'Both parts are complete sentences, so a semicolon joins them.', w: ['', 'A comma alone between two complete sentences is a comma splice.', 'With no punctuation, two complete sentences run together.', 'No comma belongs after “and”.'] },
  { d: 1, ps: 'Because the main road was ______ the bus took a longer route through the hills.', p: Q_SEC, o: ['closed,', 'closed;', 'closed:', 'closed'], a: 0, x: 'An opening “Because…” clause is followed by a comma.', w: ['', 'A semicolon needs a complete sentence before it, but the “Because…” clause isn’t one.', 'A colon needs a complete sentence before it.', 'Without a comma, “closed the bus” runs together.'] },
  { d: 2, ps: 'Sloths move very ______ they spend most of their lives hanging upside down in trees.', p: Q_SEC, o: ['slowly;', 'slowly,', 'slowly', 'slowly, and,'], a: 0, x: 'Both parts are complete sentences, so a semicolon joins them.', w: ['', 'A comma alone between two complete sentences is a comma splice.', 'With no punctuation, two complete sentences run together.', 'No comma belongs after “and”.'] },
  { d: 2, ps: 'The chef’s signature dish has three main ______ fresh pasta, wild mushrooms, and a drizzle of truffle oil.', p: Q_SEC, o: ['ingredients:', 'ingredients;', 'ingredients, such as:', 'ingredients'], a: 0, x: 'A complete sentence introduces the list, so a colon fits.', w: ['', 'A semicolon can’t introduce a list.', 'A colon can’t follow “such as”.', 'Without punctuation, the list runs straight into “ingredients”.'] },
  { d: 2, ps: 'Jane Goodall, who began studying chimpanzees in Tanzania in ______ discovered that they make and use tools.', p: Q_SEC, o: ['1960,', '1960', '1960;', '1960:'], a: 0, x: 'The “who” clause opens with a comma, so it must close with one before the verb “discovered”.', w: ['', 'The clause opens with a comma, so it needs a closing comma before “discovered”.', 'A semicolon would cut the subject off from its verb.', 'A colon would cut the subject off from its verb.'] },
  { d: 2, ps: 'The bridge—one of the longest in the ______ took nearly ten years to build.', p: Q_SEC, o: ['country—', 'country,', 'country;', 'country'], a: 0, x: 'The description opens with a dash, so it must close with a dash before “took”.', w: ['', 'The description opens with a dash, so it must close with a dash, not a comma.', 'A semicolon would cut the subject off from its verb, “took”.', 'Without a closing dash, the description runs into the verb.'] },
  { d: 2, ps: 'After hours of searching, the hikers finally found the ______ behind a curtain of vines, it was smaller than they had expected.', p: Q_SEC, o: ['cave. Hidden', 'cave, hidden', 'cave hidden', 'cave; and hidden'], a: 0, x: '“Hidden behind a curtain of vines, it was smaller…” is a complete sentence, so it must start after a period.', w: ['', 'This joins two complete sentences with only a comma, a comma splice.', 'With no punctuation, the two sentences run together.', 'A semicolon shouldn’t be followed by “and”.'] },
  { d: 3, ps: 'The ______ old farmhouse at the end of the road was finally sold last spring.', p: Q_SEC, o: ['creaky, drafty', 'creaky drafty', 'creaky, drafty,', 'creaky; drafty'], a: 0, x: '“Creaky” and “drafty” each describe the farmhouse equally (you could say “drafty and creaky”), so a comma separates them. No comma goes before “old farmhouse”.', w: ['', 'Two adjectives that equally describe a noun need a comma between them.', 'No comma belongs between the last adjective and what it describes.', 'A semicolon can’t separate adjectives.'] },
  { d: 3, ps: 'The novel’s ______ a former sailor who returns home after twenty years—discovers that no one in his village recognizes him.', p: Q_SEC, o: ['narrator—', 'narrator,', 'narrator:', 'narrator'], a: 0, x: 'The description closes with a dash before “discovers”, so it must open with a dash.', w: ['', 'The description closes with a dash, so it must open with one, not a comma.', 'The description closes with a dash, so it must open with one, not a colon.', 'Without opening punctuation, the description runs into “narrator”.'] },
  { d: 3, ps: 'Many of the town’s oldest buildings were damaged in the ______ several, however, survived with only minor cracks.', p: Q_SEC, o: ['earthquake;', 'earthquake,', 'earthquake', 'earthquake, and,'], a: 0, x: '“Several, however, survived…” is a complete sentence, so a semicolon separates it from the first. “However” sits inside the second sentence.', w: ['', 'A comma alone between two complete sentences is a comma splice.', 'With no punctuation, two complete sentences run together.', 'No comma belongs after “and”.'] },
  { d: 3, ps: 'Two species of finch live on the ______ one with a thick beak for cracking seeds, the other with a thin beak for catching insects.', p: Q_SEC, o: ['island:', 'island;', 'island, and', 'island'], a: 0, x: 'A complete sentence comes first, and what follows describes the two species, so a colon fits.', w: ['', 'A semicolon needs a complete sentence after it, but “one with a thick beak…” isn’t one.', '“And one with a thick beak…” isn’t a complete sentence, so it can’t follow “and” like this.', 'Without punctuation, the description runs into “island”.'] },
  { d: 3, ps: 'The museum is usually crowded on ______ on weekday mornings, however, its galleries are often nearly empty.', p: Q_SEC, o: ['weekends;', 'weekends,', 'weekends', 'weekends:'], a: 0, x: 'Two complete sentences are joined, so a semicolon is needed; “however” belongs to the second sentence.', w: ['', 'A comma alone between two complete sentences is a comma splice.', 'With no punctuation, two complete sentences run together.', 'A colon introduces an explanation, but the second sentence contrasts with the first.'] },
  { d: 3, ps: 'Leonardo da Vinci’s ______ was stolen from the Louvre in 1911 and recovered two years later.', p: Q_SEC, o: ['*Mona Lisa*', '*Mona Lisa*,', ', *Mona Lisa*,', ', *Mona Lisa*'], a: 0, x: 'The title identifies which painting, so it isn’t set off with commas, and nothing separates the subject from “was stolen”.', w: ['', 'A comma here separates the subject from its verb.', 'Commas around the title would suggest it’s his only painting, which isn’t true.', 'A comma before the title splits the subject.'] },
  { d: 3, ps: 'The volunteers planted three kinds of ______ oaks, which grow slowly but live for centuries; maples; and birches, which grow quickly.', p: Q_SEC, o: ['trees:', 'trees;', 'trees,', 'trees'], a: 0, x: 'A complete sentence introduces the list, so a colon fits. The list uses semicolons because some items contain commas.', w: ['', 'A semicolon can’t introduce a list.', 'A comma here makes it hard to tell where the list begins, since the items already contain commas.', 'Without punctuation, the list runs into “trees”.'] },
  { d: 3, ps: 'Jonas Salk, who developed the first widely used polio vaccine, famously declined to patent ______ asked who owned it, he replied that it belonged to the people.', p: Q_SEC, o: ['it; when', 'it, when', 'it when', 'it, and, when'], a: 0, x: '“When asked who owned it, he replied…” is a complete sentence, so a semicolon separates it from the first.', w: ['', 'A comma alone between two complete sentences is a comma splice.', 'With no punctuation, two complete sentences run together.', 'No comma belongs after “and”.'] }
]);
drillSet('fss', 2, [
  { d: 1, ps: 'The kittens ______ asleep in a basket by the fire.', p: Q_SEC, o: ['are', 'is', 'was', 'has been'], a: 0, x: '“Kittens” is plural, so the verb is “are”.', w: ['', '“Is” is singular, but “kittens” is plural.', '“Was” is singular, but “kittens” is plural.', '“Has been” is singular, but “kittens” is plural.'] },
  { d: 1, ps: 'Yesterday, our teacher ______ us a story about her trip to Peru.', p: Q_SEC, o: ['told', 'tells', 'will tell', 'is telling'], a: 0, x: '“Yesterday” calls for the past tense: “told”.', w: ['', '“Tells” is present tense, but “yesterday” is in the past.', '“Will tell” is future tense, but “yesterday” is in the past.', '“Is telling” is present tense, but “yesterday” is in the past.'] },
  { d: 2, ps: 'The sound of the waves ______ the children to sleep every night.', p: Q_SEC, o: ['lulls', 'lull', 'are lulling', 'have lulled'], a: 0, x: 'The subject is “sound” (singular), not “waves”, so the verb is “lulls”.', w: ['', '“Lull” is plural, but the subject “sound” is singular.', '“Are lulling” is plural, but “sound” is singular.', '“Have lulled” is plural, but “sound” is singular.'] },
  { d: 2, ps: 'The museum displayed the ______ final paintings, completed just before she died, in a room of their own.', p: Q_SEC, o: ['artist’s', 'artists’', 'artists', 'artist'], a: 0, x: 'One artist (“she”) owns the paintings, so the singular possessive “artist’s” is needed.', w: ['', '“Artists’” means several artists, but “she” shows there is one.', '“Artists” has no apostrophe, so it doesn’t show possession.', '“Artist” without an apostrophe doesn’t show the paintings are hers.'] },
  { d: 2, ps: 'Each of the swallows built ______ nest high on the cliff.', p: Q_SEC, o: ['its', 'their', 'it’s', 'they’re'], a: 0, x: '“Each” is singular, so the possessive is “its”.', w: ['', '“Each” is singular, so “their” doesn’t agree.', '“It’s” means “it is”.', '“They’re” means “they are”.'] },
  { d: 2, ps: 'Swimming across the bay, ______', p: Q_SEC, o: ['the athletes battled strong currents.', 'strong currents slowed the athletes.', 'the bay’s currents were stronger than expected.', 'there were strong currents for the athletes.'], a: 0, x: 'The ones swimming are the athletes, so “the athletes” must come right after the comma.', w: ['', 'This makes it sound like the currents were swimming across the bay.', 'This makes it sound like the currents were swimming.', 'This leaves no one doing the swimming.'] },
  { d: 2, ps: 'The museum’s new exhibit, which ______ more than 200 photographs, opens next week.', p: Q_SEC, o: ['includes', 'include', 'are including', 'have included'], a: 0, x: '“Which” refers to “exhibit” (singular), so the verb is “includes”.', w: ['', '“Include” is plural, but “which” refers to the singular “exhibit”.', '“Are including” is plural, but “exhibit” is singular.', '“Have included” is plural, but “exhibit” is singular.'] },
  { d: 3, ps: 'Either the twins or their older brother ______ going to walk the dog tonight.', p: Q_SEC, o: ['is', 'are', 'were', 'have been'], a: 0, x: 'With “either… or”, the verb agrees with the nearer subject, “brother” (singular): “is”.', w: ['', 'The verb agrees with the nearer subject, “brother”, which is singular.', '“Were” is plural and past tense; the verb must agree with “brother”.', '“Have been” is plural; the verb must agree with “brother”.'] },
  { d: 3, ps: 'Among the most famous of the ancient wonders ______ the Hanging Gardens of Babylon, which may never have existed at all.', p: Q_SEC, o: ['are', 'is', 'was', 'has been'], a: 0, x: 'The sentence is inverted: the subject, “the Hanging Gardens”, comes after the verb and is plural.', w: ['', 'The subject “the Hanging Gardens” is plural.', '“Was” is singular, but “the Hanging Gardens” is plural.', '“Has been” is singular, but the subject is plural.'] },
  { d: 3, ps: 'The committee will announce ______ decision after it has reviewed all of the applications.', p: Q_SEC, o: ['its', 'their', 'it’s', 'they’re'], a: 0, x: 'The committee acts as one group (“it has reviewed”), so the possessive is “its”.', w: ['', 'The sentence treats the committee as singular (“it has reviewed”), so “their” doesn’t agree.', '“It’s” means “it is”.', '“They’re” means “they are”.'] },
  { d: 3, ps: 'The bell had ______ three times before the students noticed it.', p: Q_SEC, o: ['rung', 'rang', 'ringed', 'ring'], a: 0, x: 'After “had”, use the past participle: ring, rang, rung.', w: ['', '“Rang” is the simple past; after “had” you need “rung”.', '“Ringed” means circled, not the sound of a bell.', '“Had ring” isn’t a correct verb form.'] },
  { d: 3, ps: 'Having been warned about the approaching storm, ______', p: Q_SEC, o: ['the sailors stayed in the harbor.', 'the harbor was full of boats.', 'the storm passed without damage.', 'staying in the harbor seemed wise to the sailors.'], a: 0, x: 'The ones warned are the sailors, so “the sailors” must come right after the comma.', w: ['', 'This makes it sound like the harbor was warned.', 'This makes it sound like the storm was warned about itself.', 'This makes it sound like “staying” was warned.'] },
  { d: 3, ps: 'The doctor recommended that each patient ______ at least eight glasses of water a day.', p: Q_SEC, o: ['drink', 'drinks', 'drank', 'is drinking'], a: 0, x: 'After “recommended that”, the verb takes its base form (“drink”), even with a singular subject.', w: ['', 'After “recommended that”, use the base form, “drink”.', '“Drank” is past tense, but a recommendation is about what should happen.', '“Is drinking” describes what is happening, not what should happen.'] },
  { d: 3, ps: 'Few of the paintings in the exhibition ______ been shown in public before.', p: Q_SEC, o: ['have', 'has', 'is', 'was'], a: 0, x: '“Few” is plural, so the verb is “have”.', w: ['', '“Has” is singular, but “few” is plural.', '“Is” is singular, and “is been” isn’t a correct form.', '“Was” is singular, and “was been” isn’t a correct form.'] },
  { d: 3, ps: 'The coach told her players that she valued effort more than talent and that teamwork mattered more than ______', p: Q_SEC, o: ['individual glory.', 'being individually glorious.', 'how glorious each player was.', 'players who are glorious.'], a: 0, x: 'The two comparisons should match: “effort more than talent” and “teamwork more than individual glory” (noun and noun).', w: ['', '“Being individually glorious” doesn’t match the noun “teamwork”.', 'A clause doesn’t match the noun “teamwork”.', 'This compares teamwork with people, which isn’t parallel.'] }
]);
drillSet('trn', 2, [
  { d: 1, ps: 'It rained heavily all morning. ______ the soccer game was postponed until the next day.', p: Q_TRN, o: ['Therefore,', 'However,', 'For example,', 'Similarly,'], a: 0, x: 'The game was postponed because of the rain: cause and effect.', w: ['', 'Postponing the game follows from the rain; it isn’t a contrast.', 'Postponing the game isn’t an example of rain.', 'Postponing isn’t similar to raining; it’s a result.'] },
  { d: 1, ps: 'Lions live in groups called prides. ______ tigers usually live and hunt alone.', p: Q_TRN, o: ['In contrast,', 'Similarly,', 'For example,', 'As a result,'], a: 0, x: 'Living alone is the opposite of living in groups: a contrast.', w: ['', 'Tigers live alone, unlike lions, so they aren’t similar.', 'Tigers aren’t an example of animals living in prides.', 'Tigers living alone isn’t a result of lions living in groups.'] },
  { d: 1, ps: 'Many fruits are rich in vitamin C. ______ oranges, strawberries and kiwis all contain large amounts of it.', p: Q_TRN, o: ['For example,', 'However,', 'Instead,', 'In contrast,'], a: 0, x: 'Oranges, strawberries and kiwis are examples of fruits rich in vitamin C.', w: ['', 'The fruits agree with the first sentence; nothing contrasts.', '“Instead” signals a replacement, but these are examples.', 'The second sentence supports the first rather than contrasting with it.'] },
  { d: 2, ps: 'The museum owns one of the world’s largest collections of ancient coins. ______ the collection is rarely displayed, because the coins are fragile and difficult to protect.', p: Q_TRN, o: ['However,', 'Therefore,', 'For instance,', 'Likewise,'], a: 0, x: 'Owning a huge collection but rarely showing it is a contrast.', w: ['', 'Rarely displaying the coins isn’t a result of owning many; the reason given is fragility.', 'Rarely displaying the coins isn’t an example of owning a large collection.', 'The second sentence contrasts with the first; it isn’t similar.'] },
  { d: 2, ps: 'Studies show that regular exercise improves heart health. ______ it can reduce stress and improve sleep.', p: Q_TRN, o: ['In addition,', 'In contrast,', 'For example,', 'Instead,'], a: 0, x: 'The second sentence adds more benefits of exercise.', w: ['', 'More benefits don’t contrast with heart health.', 'Reducing stress isn’t an example of heart health.', '“Instead” signals a replacement, but these are additional benefits.'] },
  { d: 2, ps: 'The team was losing by ten points at halftime. ______ it rallied in the second half and won the game by three.', p: Q_TRN, o: ['Nevertheless,', 'As a result,', 'Similarly,', 'For example,'], a: 0, x: 'Winning despite trailing badly is an unexpected outcome: “Nevertheless”.', w: ['', 'Winning wasn’t caused by losing at halftime.', 'Winning isn’t similar to losing at halftime.', 'Winning isn’t an example of losing at halftime.'] },
  { d: 2, ps: 'The author’s first novel was rejected by twelve publishers. ______ it was published and went on to sell millions of copies.', p: Q_TRN, o: ['Eventually,', 'Consequently,', 'Similarly,', 'For instance,'], a: 0, x: 'After many rejections, it was published in the end: “Eventually”.', w: ['', 'Being published wasn’t caused by being rejected.', 'Success isn’t similar to rejection.', 'Success isn’t an example of being rejected.'] },
  { d: 2, ps: 'Some plants need full sunlight to grow well. Others, ______ thrive in the shade of taller trees.', p: Q_TRN, o: ['however,', 'therefore,', 'for example,', 'similarly,'], a: 0, x: 'Plants that thrive in shade contrast with plants that need full sun.', w: ['', 'Thriving in shade isn’t a result of other plants needing sun.', 'Shade plants aren’t an example of plants that need full sun.', 'Shade plants aren’t similar to sun-loving plants.'] },
  { d: 3, ps: 'The new treatment reduced symptoms in most patients. ______ it caused serious side effects in a few, so doctors recommend it only for severe cases.', p: Q_TRN, o: ['That said,', 'Accordingly,', 'Specifically,', 'In other words,'], a: 0, x: 'The second sentence adds a qualification to the good news: “That said”.', w: ['', 'Side effects aren’t a result of reducing symptoms.', '“Specifically” would add detail about how symptoms were reduced, not a drawback.', 'The second sentence adds new information; it doesn’t restate the first.'] },
  { d: 3, ps: 'The ancient Egyptians built pyramids as tombs for their rulers. The Maya, ______ built most of their pyramids as platforms for temples, with steep stairs leading to a shrine at the top.', p: Q_TRN, o: ['by contrast,', 'therefore,', 'for example,', 'likewise,'], a: 0, x: 'The Maya used pyramids differently from the Egyptians: a contrast.', w: ['', 'The Maya’s practice wasn’t a result of the Egyptians’.', 'The Maya aren’t an example of the Egyptians’ practice.', 'The Maya used pyramids differently, so “likewise” is wrong.'] },
  { d: 3, ps: 'Critics expected the small, quiet film to disappear from theaters within a week. ______ it played for months, drawing larger crowds each weekend as word spread.', p: Q_TRN, o: ['Instead,', 'Similarly,', 'Thus,', 'Moreover,'], a: 0, x: 'The film did the opposite of what critics expected: “Instead”.', w: ['', 'Playing for months isn’t similar to disappearing quickly.', 'Playing for months isn’t a result of critics’ expectations.', '“Moreover” adds a similar point, but this contradicts the expectation.'] },
  { d: 3, ps: 'The researchers’ first experiment showed that the drug lowered blood pressure in mice. ______ they could not yet say whether it would work in humans, since many drugs that help mice fail in people.', p: Q_TRN, o: ['Still,', 'Therefore,', 'Moreover,', 'For instance,'], a: 0, x: 'Despite the good result, they couldn’t yet conclude it works in people: “Still” introduces that limit.', w: ['', 'Being unable to say isn’t a result of the drug working in mice.', '“Moreover” would add another positive point, but this is a limitation.', 'The limitation isn’t an example of the mouse result.'] },
  { d: 3, ps: 'Volcanic eruptions can be enormously destructive. ______ the ash they leave behind eventually breaks down into some of the most fertile soil on Earth.', p: Q_TRN, o: ['At the same time,', 'For example,', 'In other words,', 'Similarly,'], a: 0, x: 'The second sentence offers a contrasting truth about eruptions alongside the first: “At the same time”.', w: ['', 'Fertile soil isn’t an example of destruction.', 'The second sentence doesn’t restate the first; it adds a benefit.', 'Creating fertile soil isn’t similar to being destructive.'] },
  { d: 3, ps: 'The city’s population grew by 40 percent in a single decade. ______ the number of buses on its streets stayed almost the same, and riders complained about crowding.', p: Q_TRN, o: ['Yet', 'Accordingly,', 'Likewise,', 'In fact,'], a: 0, x: 'A big population increase with no more buses is an unexpected contrast: “Yet”.', w: ['', '“Accordingly” would mean the buses stayed the same because the population grew, which makes no sense.', 'The buses didn’t grow like the population.', '“In fact” would strengthen the first point, but this sentence contrasts with it.'] },
  { d: 3, ps: 'Scientists once thought that the human appendix served no purpose. ______ some researchers believe that it may store helpful bacteria that can repopulate the gut after an illness.', p: Q_TRN, o: ['In recent years, however,', 'For this reason,', 'In other words,', 'Likewise,'], a: 0, x: 'The newer view contrasts with the older belief and comes later in time.', w: ['', 'The new view isn’t a result of the old belief.', 'The new view doesn’t restate the old one; it contradicts it.', 'The new view isn’t similar to the old one.'] }
]);
drillSet('rsy', 2, [
  { d: 1, ps: NOTES + '- The Pacific Ocean is the largest ocean on Earth.\n- It covers about one-third of the planet’s surface.\n- It contains thousands of islands.', p: 'The student wants to state how much of Earth’s surface the Pacific Ocean covers. ' + Q_RSY, o: ['The Pacific Ocean covers about one-third of Earth’s surface.', 'The Pacific Ocean is the largest ocean on Earth.', 'The Pacific Ocean contains thousands of islands.', 'The Pacific is one of Earth’s oceans.'], a: 0, x: 'Only one choice gives how much of the surface it covers.', w: ['', 'This says it’s the largest but not how much of the surface it covers.', 'This is about islands, not surface area.', 'This gives no information about its size.'] },
  { d: 1, ps: NOTES + '- Wolfgang Amadeus Mozart was born in Salzburg in 1756.\n- He began composing music at the age of five.\n- He wrote more than 600 works.', p: 'The student wants to emphasize how young Mozart was when he began composing. ' + Q_RSY, o: ['Mozart began composing music when he was only five years old.', 'Mozart was born in Salzburg in 1756.', 'Mozart wrote more than 600 works.', 'Mozart was a composer from Salzburg.'], a: 0, x: 'Only one choice gives the age when he started composing.', w: ['', 'This gives his birth, not when he began composing.', 'This is about how much he wrote, not when he began.', 'This doesn’t mention his age.'] },
  { d: 1, ps: NOTES + '- The bald eagle is the national bird of the United States.\n- It eats mainly fish.\n- It builds some of the largest nests of any bird.', p: 'The student wants to describe what bald eagles eat. ' + Q_RSY, o: ['Bald eagles eat mainly fish.', 'The bald eagle is the national bird of the United States.', 'Bald eagles build some of the largest nests of any bird.', 'Bald eagles are large birds.'], a: 0, x: 'Only one choice is about food.', w: ['', 'This is about its status, not its food.', 'This is about nests, not food.', 'This is about size, not food.'] },
  { d: 2, ps: NOTES + '- The Arctic and the Antarctic are both cold polar regions.\n- The Arctic is an ocean surrounded by land.\n- The Antarctic is a continent, land surrounded by ocean.', p: 'The student wants to contrast the geography of the two regions. ' + Q_RSY, o: ['The Arctic is an ocean surrounded by land, while the Antarctic is land surrounded by ocean.', 'The Arctic and the Antarctic are both cold polar regions.', 'The Antarctic is a continent.', 'The Arctic is a cold region.'], a: 0, x: 'Only one choice sets the two regions’ geography side by side.', w: ['', 'This is a similarity, not a contrast.', 'This describes one region only.', 'This describes one region only.'] },
  { d: 2, ps: NOTES + '- Wangari Maathai founded the Green Belt Movement in Kenya in 1977.\n- The movement trains people, especially women, to plant trees.\n- It has planted more than 50 million trees.\n- In 2004, Maathai became the first African woman to win the Nobel Peace Prize.', p: 'The student wants to emphasize the scale of the Green Belt Movement’s work. ' + Q_RSY, o: ['The Green Belt Movement, founded by Wangari Maathai in 1977, has planted more than 50 million trees.', 'In 2004, Maathai became the first African woman to win the Nobel Peace Prize.', 'The Green Belt Movement trains people, especially women, to plant trees.', 'Wangari Maathai founded the Green Belt Movement in Kenya.'], a: 0, x: 'The number of trees planted shows the scale of the work.', w: ['', 'This is about Maathai’s prize, not the movement’s scale.', 'This describes what the movement does, but not how much.', 'This says who founded it, not the scale of its work.'] },
  { d: 2, ps: NOTES + '- Researchers studied whether a later school start time improves attendance.\n- They compared 20 schools that moved their start from 7:30 to 8:30 with 20 schools that did not change.\n- Attendance rose by 4% at the schools that started later.\n- Attendance did not change at the other schools.', p: 'The student wants to present the study’s main finding. ' + Q_RSY, o: ['Attendance rose by 4% at schools that moved their start time later, but it did not change at schools that kept their start time.', 'Researchers compared 20 schools that changed their start time with 20 that did not.', 'Researchers studied whether a later start time improves attendance.', 'Some schools moved their start time from 7:30 to 8:30.'], a: 0, x: 'The finding compares attendance at the two kinds of schools; only one choice gives it.', w: ['', 'This describes the method, not the finding.', 'This gives the research question, not the finding.', 'This describes part of the method, not the finding.'] },
  { d: 2, ps: NOTES + '- Saturn is the sixth planet from the Sun.\n- It has more known moons than any other planet.\n- Its rings are made mostly of chunks of ice.\n- The rings are about 280,000 kilometers across but, in many places, only about 10 meters thick.', p: 'The student wants to emphasize how thin Saturn’s rings are. ' + Q_RSY, o: ['Although Saturn’s rings stretch about 280,000 kilometers across, in many places they are only about 10 meters thick.', 'Saturn’s rings are made mostly of chunks of ice.', 'Saturn has more known moons than any other planet.', 'Saturn’s rings are about 280,000 kilometers across.'], a: 0, x: 'Comparing the huge width with the tiny thickness emphasizes how thin the rings are.', w: ['', 'This is about what the rings are made of.', 'This is about moons, not rings.', 'This gives only the width, which makes the rings sound large, not thin.'] },
  { d: 2, ps: NOTES + '- Frida Kahlo (1907–1954) was a Mexican painter.\n- She painted many self-portraits.\n- Many of her paintings show traditional Mexican clothing and native plants.\n- She once said, “I paint myself because I am so often alone.”', p: 'The student wants to explain, in Kahlo’s own words, why she painted so many self-portraits. ' + Q_RSY, o: ['Kahlo, who painted many self-portraits, once said, “I paint myself because I am so often alone.”', 'Many of Kahlo’s paintings show traditional Mexican clothing and native plants.', 'Frida Kahlo (1907–1954) was a Mexican painter.', 'Kahlo painted many self-portraits.'], a: 0, x: 'Only one choice gives her own explanation.', w: ['', 'This describes what appears in her paintings, not why she painted herself.', 'This identifies her without explaining her self-portraits.', 'This says she painted them but not why.'] },
  { d: 3, ps: NOTES + '- Two cities tried different ways to reduce traffic.\n- City A added a new lane to its main highway.\n- Within three years, traffic in City A had returned to its old levels.\n- City B added bus lanes and raised parking fees downtown.\n- Traffic in City B fell by 15% and stayed lower.', p: 'The student wants to contrast the long-term results of the two approaches. ' + Q_RSY, o: ['While traffic in City A returned to its old levels within three years of adding a highway lane, traffic in City B fell by 15% and stayed lower after it added bus lanes and raised parking fees.', 'City A added a new lane to its main highway, while City B added bus lanes and raised parking fees.', 'Two cities tried different ways to reduce traffic.', 'Traffic in City B fell by 15% and stayed lower.'], a: 0, x: 'The goal is results, not methods, and both cities’ results must appear.', w: ['', 'This contrasts the approaches but not their results.', 'This introduces the topic without results.', 'This gives only City B’s result.'] },
  { d: 3, ps: NOTES + '- Tardigrades are tiny animals, less than a millimeter long.\n- They can survive temperatures close to absolute zero.\n- Some have survived being exposed to the vacuum of space.\n- They survive such conditions by drying out and entering a state called a tun.', p: 'The student wants to explain how tardigrades survive extreme conditions. ' + Q_RSY, o: ['Tardigrades survive extreme conditions, even the vacuum of space, by drying out and entering a state called a tun.', 'Tardigrades are tiny animals, less than a millimeter long.', 'Some tardigrades have survived being exposed to the vacuum of space.', 'Tardigrades can survive temperatures close to absolute zero.'], a: 0, x: 'The goal is how they survive; only one choice gives the method (the tun).', w: ['', 'This describes their size, not how they survive.', 'This shows what they survive but not how.', 'This shows what they survive but not how.'] },
  { d: 3, ps: NOTES + '- Linear B is a script used in ancient Greece from about 1450 to 1200 BCE.\n- For decades, scholars were unable to read it.\n- Many scholars assumed it recorded a language other than Greek.\n- In 1952, architect Michael Ventris showed that it recorded an early form of Greek.', p: 'The student wants to emphasize the surprising nature of Ventris’s discovery. ' + Q_RSY, o: ['Although many scholars had assumed that Linear B recorded a language other than Greek, Michael Ventris showed in 1952 that it recorded an early form of Greek.', 'Linear B is a script used in ancient Greece from about 1450 to 1200 BCE.', 'For decades, scholars were unable to read Linear B.', 'In 1952, Michael Ventris deciphered Linear B.'], a: 0, x: 'A discovery is surprising when it overturns an assumption; only one choice states both.', w: ['', 'This dates the script but says nothing about the discovery.', 'This shows the difficulty but not what made the discovery surprising.', 'This reports the discovery without the assumption it overturned.'] },
  { d: 3, ps: NOTES + '- Psychologist Leah Kim studied how people judge the speed of passing cars.\n- She wanted to know whether a car’s sound affects how fast people think it is going.\n- Participants watched videos of the same cars with either loud or quiet engine sounds.\n- Cars with louder sounds were judged to be going faster.', p: 'The student wants to present the study’s method and result to an audience unfamiliar with it. ' + Q_RSY, o: ['In a study in which participants watched videos of the same cars with either loud or quiet engine sounds, the cars with louder sounds were judged to be going faster.', 'Leah Kim wanted to know whether a car’s sound affects how fast people think it is going.', 'Cars with louder sounds were judged to be going faster.', 'Participants watched videos of cars with loud or quiet engine sounds.'], a: 0, x: 'An unfamiliar audience needs both what was done and what was found; only one choice gives both.', w: ['', 'This gives the question but neither method nor result.', 'This gives the result without the method.', 'This gives the method without the result.'] },
  { d: 3, ps: NOTES + '- Kudzu is a vine native to Japan and China.\n- It was brought to the United States in 1876.\n- In the 1930s and 1940s, it was widely planted to control soil erosion.\n- It can grow as much as 30 centimeters in a day.\n- It now covers large areas of the southeastern United States, smothering trees and other plants.', p: 'The student wants to explain how a plant introduced to solve a problem became a problem itself. ' + Q_RSY, o: ['Kudzu, widely planted to control soil erosion, grows so fast (up to 30 centimeters a day) that it now smothers trees and other plants across the southeastern United States.', 'Kudzu, a vine native to Japan and China, was brought to the United States in 1876.', 'Kudzu can grow as much as 30 centimeters in a day.', 'In the 1930s and 1940s, kudzu was widely planted to control soil erosion.'], a: 0, x: 'The goal needs the original purpose and the problem it caused; only one choice links them.', w: ['', 'This gives its origin, not how it became a problem.', 'This explains its speed but not that it was meant to help or what harm it does.', 'This gives its purpose but not the problem it became.'] },
  { d: 3, ps: NOTES + '- The James Webb Space Telescope launched in December 2021.\n- It observes mainly infrared light.\n- In 2022, it captured images of galaxies that formed less than 400 million years after the Big Bang.\n- These early galaxies were brighter and more numerous than many models had predicted.', p: 'The student wants to present a recent finding to an audience already familiar with the Webb telescope. ' + Q_RSY, o: ['In 2022, Webb captured images of galaxies that formed less than 400 million years after the Big Bang, and they were brighter and more numerous than many models predicted.', 'The James Webb Space Telescope launched in December 2021.', 'The Webb telescope observes mainly infrared light.', 'The Webb telescope has captured images of distant galaxies.'], a: 0, x: 'An audience that knows the telescope needs the finding, not background.', w: ['', 'This is background the audience already knows.', 'This is background the audience already knows.', 'This is too vague to present the specific finding.'] },
  { d: 3, ps: NOTES + '- Spanish and Portuguese are both Romance languages.\n- About 485 million people speak Spanish as a first language.\n- About 235 million people speak Portuguese as a first language.\n- Speakers of the two languages can often understand each other’s writing.', p: 'The student wants to emphasize a similarity between the two languages. ' + Q_RSY, o: ['Spanish and Portuguese, both Romance languages, are similar enough that speakers of one can often understand writing in the other.', 'About 485 million people speak Spanish as a first language, compared with about 235 million for Portuguese.', 'Portuguese has about 235 million first-language speakers.', 'More people speak Spanish than Portuguese as a first language.'], a: 0, x: 'Only one choice describes a way the languages are alike.', w: ['', 'This compares numbers of speakers, which is a difference.', 'This describes one language only.', 'This is a difference, not a similarity.'] }
]);
